COLLDATA("jamulfawaid","ur",[[349,"سیدنا ابو ہریرہ رضی اللہ عنہ کی مرفوع روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی شخص اس پانی میں بول و براز نہ کرے جو جاری نہ ہو کہ پھر اس میں وہ غسل کرے۔‘‘","",{"k":"بخاری (239)، مسلم (283)، ترمذی (68)، نسائی (399)، ابوداود (75)، ابن ماجہ (344)، احمد (10511)، دارمی (730)۔","m":"لَا يَبُولَنَّ، نَصَرَ سے نفی بانون ثقیلہ واحد مذکر غائب، ہرگز پیشاب نہ کرے۔"}],[350,"اور ان کی روایات میں ہے: ’’(بول نہ کرے) کھڑے پانی میں کہ پھر اس میں وضو کرے۔‘‘","",{"k":"ترمذی (68)، صحیح ہے، البانی: 58، بخاری (239)، مسلم (282)، نسائی (400)، ابوداود (70)، ابن ماجہ (344)، بقیہ اوپر والی تخریج ہے۔","m":"رِوَايَاتِهِ اس کا واحد رِوَايَةٌ ہے۔ ابوہریرہ رضی اللہ عنہ کی روایات میں سے ہے۔"}],[351,"اور ان ہی میں یہ بھی ہے: ’’کھڑے پانی میں اور نہ اس میں جنابت سے غسل کرے۔‘‘","",{"k":"ابوداود (70)، حسن، صحیح، البانی: 63، بقیہ تخریج 350 والی ہے۔","m":"وَمِنْهَا ان روایات میں سے۔ اَلدَّائِم اسم فاعل ہے، ہمیشہ رہنے والا، مراد وہ پانی بہتا نہ ہو۔"}],[352,"اور ان ہی میں یہ بھی ہے: لوگوں نے کہا: اے ابو ہریرہ! پھر ہم کیسے غسل کریں؟ تو انہوں نے کہا: ہاتھ سے پانی لے۔","",{"k":"مسلم (283)، نسائی (396)، ابوداود (70)، ابن ماجہ (605)۔","m":"يَتَنَاوَلُهُ تفاعل سے مضارع معلوم واحد مذکر غائب، ضمیر مفعول یہ پانی کی جانب لوٹتی ہے، اسے ہاتھ سے لے۔","e":"ان تمام روایات کا مفاد یہ ہے کہ ٹھہرے ہوئے پانی میں پیشاب کرنا منع ہے اور جنابت کی حالت میں ٹھہرے ہوئے پانی میں سے غسل کرنا بھی منع ہے۔ یاد رہے کہ اگر پانی جاری ہو تو پھر بھی اس میں پیشاب کرنے کی ممانعت ہے، اگر سخت مجبوری ہو تو پھر گنجائش ہے۔ پانی میں پیشاب کرنے کی ممانعت کی وجہ یہ ہے کہ پانی نجس ہو سکتا ہے، دوسرا یہ ہے کہ اگر ایک پیشاب کرے گا پھر دوسرا کرے گا تو پانی کا تقدس ختم ہو جاتا ہے۔ یہاں تھوڑی سی وضاحت کی ضرورت ہے کہ وہ پانی جو ٹھہرا ہوا ہے، اگر دو مٹکوں جتنا ہو یا اس سے زیادہ ہو تو پیشاب سے نجس نہ ہوگا اگر اس پیشاب سے اس کا رنگ، بو، ذائقہ تبدیل نہ ہوا ہو۔ اگر اس پیشاب کی وجہ سے اس کا رنگ، بو، ذائقہ تبدیل ہو چکا ہوگا تو پھر یہ ٹھہرا ہوا پانی پلید ہوگا۔ اگر یہ ٹھہرا ہوا پانی دو مٹکوں سے کم تھا، تو اس میں پیشاب کیا جائے تو یہ پلید ہوگا۔ رنگ، بو، ذائقہ بدلا ہو یا نہ بدلا ہو۔ (مرعاۃ: ۱/۵۲۳) تاہم راقم کے نزدیک حدیث کا تقاضا یہی ہے کہ پانی زیادہ ہو یا کم ہو ٹھہرا ہوا ہو تو اس میں پیشاب کرنا منع ہے جو قصداً کرے گا وہ حدیث کا نافرمان ہے، اگر کوئی کر دیتا ہے تو ہماری اوپر بیان کردہ وضاحت پر عمل کیا جائے۔ یہی صورت حال جنبی کے غسل کی ہے، اس کے لیے سیدنا ابو ہریرہ رضی اللہ عنہ نے نہایت عمدہ طریقہ بیان کیا ہے کہ اس ٹھہرے ہوئے پانی سے چلو بھر کر باہر نکال لے اور اس سے وضو یا غسل کرے تاکہ وہ جنابت والا پانی اس میں نہ گرے اور نہ ہی کوئی وسوسہ جنم لے۔"}],[353,"یحییٰ بن عبدالرحمن بن حاطب سے مروی ہے کہ عمر رضی اللہ عنہ سفری قافلے کے ساتھ جا رہے تھے۔ جن میں عمرو بن العاص رضی اللہ عنہ بھی تھے۔ جب ایک تالاب پر پہنچے تو عمرو بن العاص رضی اللہ عنہ نے تالاب کے مالک کو کہا: اے حوض والے! کیا تیرے حوض سے درندے بھی پانی پینے کے لیے وارد ہوتے ہیں؟ عمر رضی اللہ عنہ نے کہا: اے حوض والے! ہمیں خبر نہ دے ہم درندوں کے بعد گھاٹ پر اترتے ہیں اور وہ ہمارے بعد اترتے ہیں۔ (الموطا)","",{"k":"یہ اثر مرسل منقطع ہے، موطا مالک (45) علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں یہ اثر منقطع ہے۔ اور ابن ماجہ میں سیدنا ابوسعید رضی اللہ عنہ سے جو حدیث آتی ہے کہ درندوں کا جوٹھا پانی پاک ہے، وہ بہت ہی ضعیف ہے۔ استدلال کے قابل نہیں۔ (مرعاۃ: 1/550) مسئلہ: یادر ہے کہ بلی کا جوٹھا پانی پلید نہیں اسے پیا بھی جا سکتا ہے اور اس سے وضو یا غسل بھی جائز ہے۔ (مشکوٰۃ، کتاب الطہارۃ، باب احکام المیاہ: 486)"}],[354,"رزین نے کہا: بعض راویوں نے عمر رضی اللہ عنہ کا یہ قول مزید نقل کیا ہے: اور میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ نے فرمایا: درندوں کے لیے وہ ہے جو انہوں نے اپنے پیٹ میں بھر لیا ہے اور جو باقی بچا ہے وہ ہمارے لیے طہارت کرنے اور پینے کے لیے ہے۔"],[355,"حمید احمیری نے کہا: میں اس صحابی رضی اللہ عنہ سے ملا جو چار سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا ہے جیسے ابو ہریرہ رضی اللہ عنہ رہے ہیں۔ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے عورت کو مرد کے پس ماندہ پانی سے غسل کرنے سے اور مرد کو عورت کے بچے ہوئے پانی سے غسل کرنے سے منع فرمایا ہے البتہ دونوں بیک وقت برتن سے چلو بھر کے پانی لیا کریں۔","",{"k":"یہ بھی ضعیف ہے۔ (حوالہ مذکور)","m":"لَقِيتُ، عَلِمَ سے ماضی واحد متکلم، میں ملا صَحِبَ، عَلِمَ سے ماضی واحد مذکر غائب۔ ساتھی رہا۔ بِفَضْلِ باقی بچا ہوا۔ وَلْيَغْتَرِفَا افتعال سے امر غائب تثنیہ مذکر، دو چلووں بھریں۔"}],[356,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی بعض ازواج مطہرات نے بڑے ٹپ سے غسل کیا اور پھر رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور آپ صلی اللہ علیہ وسلم نے وضو یا غسل کرنا چاہا تو ام المومنین نے کہا: میں جنابت سے تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پانی جنبی نہیں ہوتا۔‘‘ (ترمذی)","",{"k":"ابوداود (81)، نسائی (238)، احمد (22622)، صحیح ہے، البانی: 74۔","m":"جَفْنَةٍ ایک ٹب میں، بڑے پیالہ میں مِنْهُ اس پانی سے لَا يُجْنِبُ، نَصَرَ سے نفی واحد مذکر غائب، پلید نہیں ہوتا۔"}],[357,"عون بن ابی جحیفہ اپنے باپ ابو جحیفہ سے بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس دوپہر کے وقت آیا۔ پانی لایا گیا۔ آپ صلی اللہ علیہ وسلم سرخ رنگ کے خیمے میں تھے۔ میں نے دیکھا کہ بلال رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے وضو کا پانی پکڑا ہوا ہے اور لوگ آپ صلی اللہ علیہ وسلم کے پس ماندہ وضو کے پانی کو آگے بڑھ کر لے رہے ہیں جس کو پانی مل جائے وہ اس کو اپنی جسم پر مل دیتا ہے اور جس کو نہ ملے وہ اپنے رفیق کے ہاتھ کی تری حاصل کرتا ہے۔","",{"k":"ترمذی (65)، ابن ماجہ (370)، البانی صحیح ہے۔ (55) (357) بخاری (5859)، مسلم (503)، نسائی (470)، ابوداود (688)، احمد (18278)، دارمی (1409)۔","m":"هُوَ آپ صلی اللہ علیہ وسلم قُبَّةٍ خیمہ۔ آدَمِ چمڑا۔ وَضُوءَ واؤ پر فتحہ ہے، وہ پانی جس سے وضو کیا جائے۔ يَبْتَدِرُونَ افتعال سے مضارع معلوم جمع مذکر غائب، لے کے جلدی کی۔ أَصَابَ ماضی افعال سے، پالیا۔ تَمَسَّحَ تفعل سے ماضی واحد مذکر غائب، مل لیا اسے۔ لَمْ يُصِبْ نفی جحد، نہ پایا۔ بَلَلِ تراوٹ۔"}],[358,"نافع راوی ہیں کہ ابن عمر رضی اللہ عنہ نے کہا: اس میں کوئی حرج نہیں کہ مرد غسل کرے عورت سے بچے ہوئے پانی کے ساتھ جب کہ وہ حائضہ نہ ہو اور وہ جنابت سے نہ ہو۔ (المالک)","",{"k":"مالک: 119۔","m":"أَنْ يُغْتَسَلَ افتعال سے مضارع مجہول، یہ کہ غسل کیا جائے۔"}],[359,"ام المومنین سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ میں اور نبی صلی اللہ علیہ وسلم ایک ہی برتن سے غسل کرتے تھے۔ برتن میں ہمارے ہاتھ آگے پیچھے آتے جاتے تھے۔","",{"k":"مسلم (321)، کتاب الحیض، بخاری (261)، ترمذی (104)، نسائی (228)، ابوداود (240)، ابن ماجہ (376)، احمد (27659)، مالک: 100، دارمی (750)۔","m":"إِنَاءٍ برتن اس کی جمع آنِيَةٌ ہے۔ تَخْتَلِفُ افتعال سے واحد مونث، حرکت کرتے، آپس میں ٹکراتے۔ فِيهِ اس برتن میں۔"}],[360,"اور اس کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم مجھ سے پہل کر جاتے اور میں کہتی تھی: میرے لیے رہنے دیجیے، میرے لیے رہنے دیجیے۔","",{"k":"مسلم (321)، بخاری (301)، ترمذی (1755)، نسائی (424)، ابوداود (2443)، ابن ماجہ (376)، احمد (27659)، مالک: 101، دارمی (750)۔","m":"فَيُبَادِرُنِي مفاعلہ سے مضارع معلوم واحد مذکر غائب، نون وقایہ، یاء مفعول بہ، مجھ سے جلدی کرتے۔ دَعْ، مَنَعَ سے امر، چھوڑ دو۔"}],[361,"اسی میں ہے: ایک برتن سے وہ بڑا پیالہ تھا جس کو فرق کہا جاتا تھا۔ سفیان نے کہا: فرق تین پیمانوں کا ہوتا ہے۔ (ص: ۴۹)","",{"k":"بخاری (250)، مسلم (316)، ترمذی (132)، نسائی (535)، ابوداود (2469)، ابن ماجہ (3653)، احمد (25746)، مالک: 693، دارمی (1058)، یہ تین صاع والی مسلم (319) میں ہے۔","m":"قَدَح پیالہ۔ اَلْفَرَقُ یہ وہ برتن ہے، جس میں تین صاع آتے ہیں تقریباً سوا چھ کلو چیز جس میں آجائے۔"}],[362,"اور اسی میں ہے: آپ صلی اللہ علیہ وسلم مجھ سے پہل کر جاتے اور میں آپ صلی اللہ علیہ وسلم سے پہل کر جاتی تھی۔ آپ صلی اللہ علیہ وسلم فرماتے: میرے لیے چھوڑ دو اور میں کہتی: میرے لیے چھوڑیئے۔","",{"k":"نسائی (239) صحیح ہے، البانی (233) بخاری (7339) مسلم (321) ترمذی (1755) ابوداود (238) ابن ماجہ (604) احمد (25756)، مالک: 101، دارمی (750)۔","m":"أُبَادِرُهُ مفاعلہ سے مضارع واحد متکلم، میں نے جلدی کی۔"}],[363,"ترمذی نے ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم میمونہ رضی اللہ عنہا کے باقی ماندہ پانی سے غسل کرتے تھے۔","",{"k":"مسلم (323)، بخاری (253)، احمد (3455)۔"}],[364,"نسائی نے ام ہانی رضی اللہ عنہا سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے اور میمونہ نے ایک بڑے پیالے سے غسل کیا جس میں آٹے کا اثر موجود تھا۔","",{"k":"نسائی (240) ابن ماجہ (378) صحیح ہے، البانی (234)","m":"قَصْعَةٍ پیالہ۔ أَثَرُ نشان۔ اَلْعَجِينُ گندھا ہوا آٹا۔"}],[365,"ابن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں مرد اور عورتیں بیک وقت ایک ہی برتن سے وضو کرتے تھے۔","",{"k":"بخاری (193)، نسائی (71)، ابوداود (79)، ابن ماجہ (381)، احمد (6247)، مالک: 46۔","m":"یَتَوَضَّأُوْنَ تفعل سے مضارع معلوم جمع مذکر غائب، وضو کرتے تھے۔","e":"۱۔ حدیث ۳۵۵ میں جو آیا ہے کہ میں ایک ایسے آدمی سے ملا جو نبی صلی اللہ علیہ وسلم کا صحابی تھا، اگر چہ ان کے نام کا علم نہیں ہو سکا چونکہ صحابی تھے اور صحابی ثقہ ہوتے ہیں، اس حدیث پر تنقید درست نہیں، یہ صحیح ہے۔ ۲۔ نمبر ۳۶۴ سے ثابت ہوتا ہے کہ کسی برتن میں گندھے ہوئے آٹے کے نشانات ہوں تو مضر نہیں اس پانی سے وضو یا غسل ہو جاتا ہے۔ ۳۔ نمبر ۳۶۵ حدیث میں جو آیا ہے، مرد اور عورتیں ایک برتن سے وضو کرتے تھے۔ اس سے غیر مرد یا غیر عورتیں مراد نہیں، میاں بیوی یا ذی محرم عورتیں مراد ہیں۔ ۴۔ علاوہ ازیں تمام احادیث آپس میں متعارض نظر آتی ہیں کہ کہیں عورت اور مرد کا ایک برتن سے وضو کرنا یا غسل کرنا جائز قرار پاتا ہے اور کسی سے ناجائز قرار پاتا ہے، تو اس میں کوئی ٹکراؤ نہیں۔ ان میں مطابقت یہ ہے کہ جو ایک دوسرے کے باقی ماندہ پانی سے وضو یا غسل کی ممانعت ہے، وہ تنزیہ اور احتیاط کے لیے ہے، حرام کے طور پر نہیں اور جن احادیث سے وضو یا غسل کی اجازت ہے ان کا مقصد یہی ہے کہ ممانعت احتیاطی ہے، وگرنہ ایک دوسرے کے بچے ہوئے پانی سے وضو یا غسل کی اجازت ہے اور استعمال شدہ پانی پاک ہے، پلید نہیں۔ اسے استعمال کر سکتے ہیں۔"}],[366,"ابن مسعود رضی اللہ عنہ سے مروی ہے کہ جنوں کی رات رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تیرے برتن میں کیا ہے؟ میں نے عرض کی: نبیذ ہے۔ فرمایا: کھجور پاک ہیں اور پانی پاک کرنے والا ہے پس آپ صلی اللہ علیہ وسلم نے اس سے وضو کیا۔","",{"k":"ترمذی (88)۔ ابوداود (84)۔ ابن ماجہ (384)۔ احمد (4284)۔ ضعیف ہے۔ البانی: 142۔"}],[367,"عبد الجبار بن وائل اپنے باپ سے روایت کرتے ہیں: میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس برتن لایا گیا۔ آپ صلی اللہ علیہ وسلم نے اس سے منہ میں پانی ڈالا اور اسی میں کلی کا پانی ڈالا جو کستوری کی مانند تھا اور کستوری سے زیادہ پاکیزہ تھا اور ناک کے پانی کو ڈول سے باہر پھینکا۔","",{"k":"ابن ماجہ (659)۔ ضعیف ہے۔ البانی: 142۔"}],[368,"ابو امامہ رضی اللہ عنہ نے ذکر کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانی کو کوئی چیز ناپاک نہیں کرتی مگر وہ چیز جو اس کی بو اور ذائقہ تبدیل کر دے۔‘‘","",{"k":"اس میں رشدین بن سعد ضعیف ہے، طبرانی کبیر: 7503۔ طبرانی اوسط ہیثمی: 1068۔ ویسے اس حدیث کے مفہوم پر علمائے کرام کا اجماع ہے۔"}],[369,"سیدنا ابو امامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بے شک پانی کو کوئی چیز پلید نہیں کرتی مگر وہ چیز جو غالب آجائے اس کی بو، ذائقہ اور رنگ پر۔‘‘","",{"k":"ابن ماجہ (521)۔ ضعیف ہے البانی: 117۔"}],[370,"سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ میں نے عرض کی: یا رسول اللہ! کیا ہم نئی ڈھانچی گئی مشک سے وضو کریں تو آپ صلی اللہ علیہ وسلم کو زیادہ پسند ہے یا وہ جس سے طہارت کی گئی ہو؟ فرمایا: بلکہ وہ جس سے طہارت کی جاتی ہے۔ اللہ کا دین آسان ہے۔ آپ صلی اللہ علیہ وسلم پیغام ارسال کرتے تھے طہارت کرانے والے کی طرف اور پانی لایا جاتا اور آپ صلی اللہ علیہ وسلم پیتے اور مسلمانوں کے ہاتھوں کی برکت کی امید رکھتے تھے۔ (الاوسط)","",{"k":"طبرانی اوسط، رجاله موثوقون، عبدالعزیز بن ابی رواد مرجئہ فرقہ جو تقدیر آگے پیچھے ہونے کا قائل ہے۔ ادھر منسوب ہے تاہم روایت میں ثقہ ہے۔ ہیثمی: 1071۔","m":"جَرّ مٹکا۔ مُخَمَّر جگہ کا نام ہے۔ اَلْمُطَاهِرِ بھی جگہ ہے۔ الْحَنِيفِيَّةُ یکطرفہ۔ اَلسَّمَحَاءُ آسان۔ يَرْجُو مضارع معلوم واحد مذکر، امید رکھتے تھے۔","e":"اس سے ثابت ہوا پینے یا غسل کرنے یا وضو کرنے کے لیے پانی ہونا چاہیے اور اس کے ساتھ ساتھ کوشش ہونی چاہیے کہ پانی بابرکت ہاتھوں یعنی نیک اور ستھرے لوگوں سے حاصل کیا جائے اور عمدہ برتنوں میں اسے محفوظ کیا جائے اور استعمال کیا جائے۔"}],[371,"ام المومنین سیدہ عائشہ رضی اللہ عنہا نے کہا: میں نے دھوپ میں پانی گرم کیا اور پھر میں نے نبی صلی اللہ علیہ وسلم کو پیش کیا تا کہ آپ صلی اللہ علیہ وسلم وضو کریں پس آپ صلی اللہ علیہ وسلم نے فرمایا: اے عائشہ! ایسا نہ کیا کر اس سے مرض پیدا ہوتی ہے۔ (الاوسط بسند ضعیف)","",{"k":"طبرانی اوسط، اس میں محمد بن مروان سدی اس کے ضعف پر اجماع ہے۔ ہیثمی: 1072۔"}],[372,"سیدنا سلمہ بن الاکوع رضی اللہ عنہ کے لیے دھوپ میں پانی گرم کیا جاتا پھر اس سے وہ وضو کرتے تھے۔ (الکبیر)","",{"k":"طبرانی کبیر: 6219۔ طبرانی کے شیخ محمد بن یونس کو میں نہیں جانتا۔ ہیثمی: 1073۔"}],[373,"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم اپنے مسواک سے بچے ہوئے پانی سے وضو کرتے تھے۔ (البزار، اعمش نے انس رضی اللہ عنہ سے نہیں سنا)","",{"k":"بزار: 274۔ اعمش نے حضرت انس سے نہیں سنا۔ ہیثمی: 1083۔"}],[374,"سیدنا عمار بن یاسر رضی اللہ عنہ سے روایت ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے دیکھا کہ میرے سامنے جو برتن رکھا تھا اس سے میں اپنے پاؤں تر کر رہا ہوں، پھر میں نے اپنے منہ یا ناک کی بلغم نکالی اور میری بلغم میرے کپڑے پر جا پڑی تو میرے سامنے جو برتن تھا اسی سے میں نے اپنا کپڑا دھونا شروع کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے عمار! تیری بلغم اور تیری آنکھوں کے آنسو اس پانی جیسے ہی ہیں جو تیرے برتن میں ہے۔ تو صرف بول براز اور منی کو زیادہ پانی سے دھویا کر اور خون اور قے کو بھی۔‘‘ (الکبیر، الاوسط، الموصلی، اور البزار بسند ضعیف)","",{"k":"طبرانی کبیر، طبرانی اوسط، ابو یعلی موصلی، بزار ضعیف ہے۔ سند کمزور ہے۔"}],[375,"ام قیس بنت محصن رضی اللہ عنہا سے مروی ہے کہ وہ اپنے چھوٹے بیٹے کو لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں۔ بچہ ابھی کھانا نہیں کھاتا تھا۔ پس آپ صلی اللہ علیہ وسلم نے اس کو گود میں لیا اور اس نے آپ صلی اللہ علیہ وسلم کے کپڑے پر پیشاب کر دیا۔ آپ صلی اللہ علیہ وسلم نے پانی منگوا کر کپڑا تر کر دیا اور دھویا نہیں۔","",{"k":"بخاری (323)۔ مسلم (2114)۔ ترمذی (71)۔ نسائی (302)۔ ابوداود (3877)۔ ابن ماجہ (3468)۔ احمد (26456)۔ مالک: 153۔ دارمی (741)۔","m":"أم قيس بنت محصن اسدیہ سیدنا عکاشہ رضی اللہ عنہ کی ہمشیرہ تھیں، کہتے ہیں اصل نام ان کا آمنہ ہے، مشہور صحابیہ رضی اللہ عنہا ہیں۔ (تقریب) أَنَّهَا یہ ام قیس۔ أَتَتْ واحد مونث غائب، باء کی وجہ سے متعدی ہے، لے آئی۔ لَهَا اس ام قیس کے لیے۔ حَجْرِہ گود میں۔ فَبَالَ ماضی واحد مذکر غائب، پیشاب کیا۔ فَنَضَحَہ ماضی واحد مذکر غائب، اس کپڑے پر پانی کے چھینٹے مارے۔"}],[376,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ آپ صلی اللہ علیہ وسلم کے پاس بچہ لایا گیا تو اس نے آپ صلی اللہ علیہ وسلم کے کپڑوں پر پیشاب کر دیا۔ آپ صلی اللہ علیہ وسلم نے پانی منگوا کر اس پر بہا دیا۔","",{"k":"بخاری (222)۔ مسلم (286)۔ نسائی (303)۔ ابوداود (5106)۔ ابن ماجہ (530)۔ احمد (25240)۔ مالک: 142۔","m":"أتى ماضی مجہول واحد مذکر غائب، یاء نے متعدی بنا دیا، لایا گیا۔ فَأَتْبَعَهُ افعال سے ماضی واحد مذکر غائب، ضمیر مفعول یہ ہے، پیشاب کی جانب لوٹتی ہے، اس کے پیچھے لگایا۔"}],[377,"لبابہ بنت حارث رضی اللہ عنہا نے کہا: حسین رضی اللہ عنہ بن علی رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی گود میں تھا اور اس نے آپ صلی اللہ علیہ وسلم کے کپڑے پر بول کر دیا تو میں نے عرض کی: یا رسول اللہ! آپ کوئی کپڑا پہن لیں اور اپنی ازار مجھے دیں تا کہ میں اس کو دھو دوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’لڑکیوں کے بول کو دھویا جاتا ہے اور لڑکے کے بول کو چھڑکاؤ کر دیا جاتا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداود (375)۔ ابن ماجہ (522)۔ البانی حسن صحیح ہے (361)۔","m":"لبابہ بنت حارث بن حزن ہلالیہ رضی اللہ عنہا ام فضل کنیت تھی۔ سیدنا عباس بن عبد المطلب رضی اللہ عنہ کی اہلیہ تھیں۔\nاور ام المومنین سیدہ میمونہ رضی اللہ عنہا کی ہمشیرہ تھیں۔ سیدنا عباس رضی اللہ عنہ کی وفات کے بعد سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پائی۔ (تقریب) اَلْبَسْ، عَلِمَ سے امر واحد مذکر غائب، پہن لو۔ وَأَعْطِنِي افعال سے امر، نون وقایہ یاء مفعول بہ ہے، اور مجھے دو۔ اِزَارَك اپنا تہبند۔"}],[378,"اور سیدنا علی رضی اللہ عنہ کی روایت میں ہے: ’’چھڑکاؤ کیا جاتا ہے جب تک بچہ کھانا نہ کھاتا ہو۔‘‘","",{"k":"ابوداود (377)۔ ترمذی (610)۔ ابن ماجہ (525)۔ احمد (564)۔ صحیح ہے اور موقوف ہے۔ البانی: 363۔","m":"لَمْ يَطْعَمْ نفی مضارع واحد مذکر غائب، نہیں کھایا۔"}],[379,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے کسی گھر میں آرام فرما رہے تھے۔ حسن رضی اللہ عنہ آئے اور چڑھتے چڑھتے نبی کریم صلی اللہ علیہ وسلم کے سینے مبارک پر جا بیٹھے اور پھر آپ کے سینے پر پیشاب کر دیا۔ میں آیا اور اس کو اتارنے لگا تو آپ بیدار ہو گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اے انس! تیرا بھلا ہو۔ میرے بیٹے اور میرے دل کے پھل کو چھوڑ دے۔ جس نے اس کو ایذا پہنچائی تو اس نے مجھے ایذا پہنچائی اور جس نے مجھے ایذا پہنچائی تو اس نے اللہ تعالیٰ کو ایذا پہنچائی پھر پانی منگوا کر اچھی طرح بول پر بہا دیا پھر فرمایا: ’’لڑکے کے بول پر پانی بہایا جاتا ہے اور لڑکی کے بول کو دھویا جاتا ہے۔‘‘ (الکبیر بسند ضعیف)","",{"k":"طبرانی کبیر (2627) اس میں راوی نافع ابو ہرمز ہے، اس کے ضعف پر اجماع ہے۔ ہیثمی (1570)۔"}],[380,"ابوالیمان المصری رحمہ اللہ نے کہا: میں نے امام الشافعی رحمہ اللہ سے سوال کیا نبی کریم صلی اللہ علیہ وسلم کی اس حدیث کے متعلق کہ لڑکے کے بول پر پانی چھڑکا جاتا ہے اور لڑکی کا بول دھویا جاتا ہے جب کہ پانی دونوں ایک ہی جیسے ہیں۔ تو انہوں نے کہا: لڑکے کا بول پانی اور مٹی سے ہے اور لڑکی کا بول گوشت اور خون سے ہے۔ اس کے بعد انہوں نے سائل کو کہا: کیا تجھے سمجھ آئی ہے؟ اس نے کہا: نہیں تو امام الشافعی رحمہ اللہ نے کہا: جب اللہ تعالیٰ نے آدم علیہ السلام کو پیدا کیا تو پھر حوا ان کی چھوٹی پسلی سے پیدا کی گئیں۔ پس لڑکے کا بول پانی اور گارے سے ہے اور لڑکی کا بول گوشت اور خون سے ہے اور پھر سائل کو کہا: تو سمجھا؟ اس نے کہا: ہاں۔ انہوں نے کہا: اللہ تعالیٰ تجھے اس سے نفع دے۔","",{"k":"ابن ماجہ (525)۔ ترمذی (610)۔ ابوداود (377)۔ احمد (1152)۔","m":"يُرَشُّ، نَصَرَ سے مضارع مجہول واحد مذکر غائب، چھڑکا جاتا ہے۔ فَهِمْتَ، عَلِمَ سے ماضی واحد مذکر حاضر، تو سمجھا۔ ضِلْعِهِ اس کی پسلی سے۔ اَلْقَصِيرِ چھوٹی۔","e":"ان تمام احادیث کا مفاد یہ ہے کہ اگر بچہ دودھ پیتا ہو اور یہی اس کی غذا ہو، کھانا نہ کھاتا ہو تو وہ پیشاب کر دے تو اس پر پانی کے چھینٹے مارے جائیں تو وہ جگہ یا کپڑا پاک ہو جاتا ہے۔ اگر بچی ہو خواہ اس کی غذا دودھ ہی ہو اس کا پیشاب لگ جائے تو اسے باقاعدہ دھویا جائے، صرف چھینٹے ہی کافی نہیں۔ اگر اس کی دودھ کے علاوہ غذا ہو کھانا وغیرہ کھاتا ہو تو پھر بچی ہو یا بچہ ہو جہاں پیشاب کرے، اسے دھویا جائے گا۔ ایک گروہ بچی یا بچے کے پیشاب میں تفریق نہیں کرتا، یہ موقف غلط ہے کیونکہ احادیث سے فرق ثابت ہوتا ہے۔ علمائے کرام نے بچی یا بچے کے پیشاب کو دھونے میں اور پانی چھڑکنے کے فرق کی وجوہات بیان کی ہیں: (۱) یہ ہے کہ بچوں کو بچیوں کی بہ نسبت زیادہ اٹھایا جاتا ہے، اگر دھونے کی پابندی لگائی جائے تو یہ گراں ہوگی۔ (۲) بچی کا پیشاب پھیلتا نہیں اسے دھونا آسان ہے، جبکہ بچے کا پیشاب پھیلتا ہے، اسے دھونا مشکل ہے۔ (۳) بچی کا پیشاب زیادہ خبیث ہے اور زیادہ بدبودار ہے اور بچے کا پیشاب اتنا نہیں۔ اصل یہ ہے کہ مذکورہ وجوہات ہوں یا نہ ہوں ہمارے لیے یہ فرض ہے کہ ہم رسول اکرم صلی اللہ علیہ وسلم کے حکم کی اطاعت کریں، وجہ خواہ کچھ بھی ہو بچہ پیشاب کرے تو پانی کے چھینٹے ماریں، بچی کرے تو اسے دھوئیں۔"}],[381,"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ ہم مسجد میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ اتنے میں ایک اعرابی شخص آیا اور مسجد میں کھڑے ہوکر پیشاب کیا: رسول اللہ صلی اللہ علیہ وسلم کے صحابہ نے کہا: ٹھہر جا ٹھہر جا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس کا پیشاب بند نہ کرو۔ چنانچہ لوگوں نے اس کو چھوڑ دیا اور اس نے پیشاب کر دیا۔ پھر آپ صلی اللہ علیہ وسلم نے اس کو بلایا اور اس کو فرمایا یہ مساجد بول براز اور گندگی ڈالنے کے لیے نہیں ہیں۔ پھر آپ صلی اللہ علیہ وسلم نے لوگوں میں سے ایک شخص کو حکم دیا تو وہ پانی کا ڈول لایا پس وہ پیشاب پر بہا دیا۔","",{"k":"مسلم (285)۔ کتاب الطہارۃ، بخاری (6025)۔ ترمذی (147)۔ نسائی (329)۔ ابن ماجہ (528)۔ احمد (12955)۔ مالک: 144۔ دارمی (0740)۔","m":"بَيْنَمَا یہ ظرف ہے، ایک دفعہ ہم۔ أَعْرَابِيٌّ دیہات میں رہنے والا ایک قول ہے، ذوخویصرہ تھا، ایک قول ہے، اقرع بن حابس تھا۔ مَهْ مَهْ یہ اسم فعل ہے، رک جا۔ یہ ڈانٹنے کا کلمہ ہے۔ اصل میں مَا هَذَا تھا۔ تخفیف کے لیے مَهْ کر دیا اور تاکید کے لیے تکرار سے آتا ہے۔ لَا تُزْرِمُوهُ افعال سے مضارع منفی جمع مذکر حاضر، نہ کاٹو۔ دَعُوهُ مثال واوی سے، امر حاضر، اس اعرابی کو چھوڑ دو۔ دَعَاهُ آپ صلی اللہ علیہ وسلم نے اس اعرابی کو بلایا۔ وَالْقَذَرِ جو چیز طبعاً قابل نفرت ہو۔ هِيَ یہ مساجد۔ فَشَنَّهُ اس پیشاب کی جگہ پر پانی بہا دیا۔ ایک نسخے میں فَسَنَّهُ سین کے ساتھ بھی ہے۔","e":"۱۔ اس سے نبی اکرم صلی اللہ علیہ وسلم کے انداز تبلیغ کی جھلک بھی نظر آتی ہے کہ نہایت ہی پرحکمت، پرتحمل اور موثر تھا۔ ۲۔ آدمی کا پیشاب نجس اور پلید ہے اور زمین پر جب یہ پیشاب ٹپکے تو وہاں سے مٹی وغیرہ اکھاڑنے کی ضرورت نہیں، اوپر پانی بہا دینا ہی کافی ہے جو اتنا زیادہ ہو کہ پیشاب پر غالب آ جائے، اس سے طہارت حاصل ہو جاتی ہے۔ ۳۔ بعض نے اس سے یہ استدلال کیا ہے کہ زمین کو نجاست لگ جائے اور وہ ہوا یا دھوپ سے خشک ہو جائے تو وہ زمین پاک نہیں ہوتی۔ یہ استدلال غلط ہے، اگر ہوا یا دھوپ کی وجہ سے نجاست کا وجود نہیں رہا تو وہ زمین پاک ہو جاتی ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے پانی اس لیے بہایا تھا کہ اس سے جلدی طہارت حاصل ہوتی ہے، یہ مطلب نہیں کہ پانی کے سوا طہارت حاصل ہی نہیں ہوتی۔ امام ابوداؤد رحمہ اللہ نے باب باندھا ہے، باب طهور الارض اذا يبست، کہ زمین جب خشک ہو جائے تو پاک ہو جاتی ہے۔\nان کے درمیان مطابقت اس طرح ہے کہ زمین نجس ہو تو اس کی طہارت دو وجہ سے حاصل ہوتی ہے: (۱) پانی ڈالنے سے۔ (۲) خشک ہونے سے، دیہاتی کے پیشاب کو صاف کرنے کے لیے نبی اکرم صلی اللہ علیہ وسلم نے ایک طریقہ اپنایا ہے، وہ پانی سے صفائی کرنے کا ہے دوسرا طریقہ یہ ہے کہ زمین خشک ہو جائے تو پاک ہو جاتی ہے۔ (مرعاۃ: ۱/۵۵۵) (۳) اس سے مسجد کے تقدس کی ترغیب بھی ثابت ہوتی ہے کہ نامناسب کاموں سے اسے بچایا جائے، بدبودار، گندی چیزیں، تنکے، تھوک وغیرہ پھینکنا ان سے احتراز کیا جائے۔ بے جا آوازیں بلند نہ کی جائیں، جھگڑا فساد نہ ہو، انہیں خرید وفروخت کا مرکز نہ بنا لیا جائے، ان میں امور خیر اور صفائی کے کام سرانجام دیے جائیں۔ ۴۔ اس حدیث سے اس غلط فہمی کا ازالہ بھی ہو جاتا ہے کہ مسجد میں نجاست ہو اس پر پانی ڈالیں تو وہ مزید نجس ہو جاتی ہے۔ یہ بات غلط ہے، بلکہ ثابت ہوتا ہے کہ اتنا زیادہ پانی بہایا گیا ہو جو نجاست کا وجود ختم کر دے اس سے زمین اور پانی دونوں پاک رہتے ہیں۔"}],[382,"سیدنا ابو ہریرہ رضی اللہ عنہ کی روایت میں ہے کہ اعرابی مسجد میں داخل ہوا اور دو رکعات نماز پڑھی پھر اس نے کہا: اے اللہ! میرے اوپر اور محمد صلی اللہ علیہ وسلم پر رحمت نازل کر اور ہمارے ساتھ کسی پر رحمت نہ کر پس آپ صلی اللہ علیہ وسلم نے فرمایا: تو نے وسیع چیز کو ہے۔ پھر اس شخص نے بلا تاخیر مسجد کے ایک طرف پیشاب کرنا شروع کر دیا تو لوگ اس کی طرف تیز رفتار سے جانے لگے نبی صلی اللہ علیہ وسلم نے لوگوں کو منع کر دیا اور فرمایا: ’’تم آسانی کے لیے بھیجے گئے ہو، تنگی کرنے کے لیے نہیں بھیجے گئے۔ اس پر پانی کا ڈول بہا دو۔‘‘","",{"k":"ترمذی (147)۔ صحیح ہے۔ البانی: 126۔ بخاری (220)۔ مسلم (284)۔ نسائی (330)۔ ابوداود (380)۔ ابن ماجہ (529)۔ احمد (11055)۔","m":"اللَّهُمَّ يَا الله سے بنا ہے۔ اے میرے اللہ! ارْحَمْنِي، عَلِمَ سے امر حاضر واحد مذکر نون وقایہ، یاء مفعول بہ ہے، مجھ پر رحم کر۔ فَالْتَفَتَ افتعال سے ماضی واحد مذکر غائب، مڑ کر دیکھا۔ تَحَجَّرْتَ تفعل سے ماضی واحد مذکر حاضر، تو نے تنگ کیا، بند کر دیا۔ فَأَسْرَعَ افعال سے ماضی واحد مذکر غائب، جلدی سے کہا۔ أَهْرِيقُوا افعال سے امر جمع مذکر حاضر ہے، ہمزہ کو ہاء سے بدل دیا گیا ہے، بہا دو۔ سَجْلًا پانی سے بھرا ڈول۔ بُعِثْتُمْ ماضی مجہول جمع مذکر حاضر تم بھیجے گئے ہو۔ مُيَسِّرِينَ تفعیل سے اسم فاعل حال ہونے کی وجہ سے منصوب ہے، اس حال میں کہ آسانی کرنے والے ہو۔ وَلَمْ تُبْعَثُوا نفی جمد جمع مذکر حاضر، تم نہیں بھیجے گئے۔ مُعَسِّرِينَ تفعیل سے اسم فاعل نصبی حالت ہے، تنگی کرنے والے۔","e":"طہارت کے متعلقہ تو بات ہو چکی ہے، اس حدیث میں اضافہ بیان ہوا ہے کہ آپ صلی اللہ علیہ وسلم نے اس دیہاتی کو دعا کرنے کا طریقہ بھی بتایا ہے کہ اللہ تعالیٰ کی وسیع رحمت سب کے لیے ہے اسے محدود نہ کیا جائے۔"}],[383,"عبد اللہ بن معقل سے مرسلا مروی ہے، اس میں یہ بھی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جس مٹی پر پیشاب پہنچا ہے اس کو اٹھا دو اور اس کی جگہ پر پانی ڈال دو۔‘‘","",{"k":"ابو داؤد (380)۔ صحیح ہے۔ البانی: 367۔ بخاری (220)۔ بخاری میں مٹی اکھاڑنے کا ذکر نہیں۔ ترمذی (147)۔ نسائی (1217)۔ ابن ماجہ (529)۔ احمد (10155)۔ ان تمام میں مٹی اکھاڑنے کا ذکر نہیں آیا۔ (شارح)","m":"أَرْسَلَهُ اسے مرسل بیان کیا ہے، یعنی تابعی سے اوپر راوی گر گیا ہے۔ وَفِيهِ اس مرسل حدیث میں ہے۔ فَأَلْقُوهُ افعال سے امر جمع مذکر حاضر، یعنی جس جگہ پر پیشاب ہوا ہے، اس سے مٹی نکالو۔","e":"اس سے وہ حضرات دلیل پکڑتے ہیں جو کہتے ہیں کہ جس جگہ پر بڑا آدمی پیشاب کرے اس جگہ کی مٹی منتقل کرنی چاہیے، اسے اکھاڑا جائے اور پھر پانی ڈالا جائے۔ یہ بات درست نہیں صحیح ترین احادیث میں دو ہی طریقے زمین پر گرنے والے پیشاب کی صفائی کے ہیں۔ (۱) دھوپ سے خشک ہو جائے۔ (۲) پانی بہا دیا جائے جیسا کہ اوپر وضاحت ہوئی ہے۔ زمین کھودنے کا طریقہ صحیح طور پر ثابت نہیں، یہ حدیث مرسل ہے جو کہ حجت نہیں۔ علامہ عبدالرحمن مبارکپوری رحمہ اللہ فرماتے ہیں، میں کہتا ہوں:\nاَلْأَحَادِيثُ الْمَرْفُوعَةُ الْمُتَّصِلَةُ الصَّحِيحَةُ خَالِيَةٌ عَنْ حَفْرِ الْأَرْضِ وَأَمَّا الْأَحَادِيثُ الَّتِي جَاءَ فِيهَا ذِكْرُ حَفْرِ الْأَرْضِ فَمِنْهَا مَا هُوَ مَوْصُولٌ فَهُوَ ضَعِيفٌ لَا يَصْلُحُ لِلِاسْتِدْلَالِ وَمِنْهَا مَا هُوَ مُرْسَلٌ فَهُوَ أَيْضًا ضَعِيفٌ عِنْدَ مَنْ لَا يَحْتَجُّ بِالْمُرْسَلِ. (تحفة الاحوذی: ۱/۱۳۹)\n’’جو احادیث صحیح، مرفوع، متصل ہیں ان میں تو زمین کھودنے کا ذکر نہیں آتا، اور جن احادیث میں یہ ذکر آتا ہے کہ پیشاب والی جگہ سے مٹی نکالی جائے، ان میں سے بعض تو موصول ہیں مگر ضعیف ہیں۔ استدلال کے قابل نہیں، بعض مرسل ہیں یہ بھی جو مرسل کو حجت نہیں سمجھتا اس کے نزدیک ضعیف ہیں۔‘‘"}],[384,"اور ان کی روایت میں سیدنا جندب رضی اللہ عنہ سے مروی ہے کہ ایک اعرابی آیا اور سواری کا اونٹ بٹھا کر اس کا زانوں باندھا اور مسجد میں داخل ہو کر آپ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی۔ جب آپ صلی اللہ علیہ وسلم نے سلام پھیرا تو اعرابی اپنی سواری کے پاس گیا، اس کا زانو کھولا، پھر سوار ہوا پھر بلند آواز سے کہا: یا اللہ! میرے اوپر اور محمد صلی اللہ علیہ وسلم پر رحمت نازل کر اور ہمارے ساتھ اس رحمت میں کسی کو شریک نہ کر۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم ان میں سے کس کو زیادہ گمراہ خیال کرو گے اس کو یا اس کے اونٹ کو؟‘‘ پھر فرمایا: ’’کیا تم نے نہیں سنا جو اس نے کہا ہے؟‘‘ تو لوگوں نے عرض کی ہاں۔","",{"k":"ابوداود (4885)۔ اس کا آخری حصہ یعنی ھو افضل الخ اس اضافہ سے یہ روایت ضعیف ہے۔ البانی: 1041۔","m":"فَأَنَاخَ افعال سے ماضی واحد مذکر غائب، اونٹ بٹھایا۔ عَقَلَهَا، ضَرَبَ سے ماضی واحد مذکر غائب ہے، اس اونٹ کا گھٹا باندھا۔ فَأَطْلَقَهَا افعال ماضی، اسے کھولا۔"}],[385,"اور مالک نے یحییٰ بن سعید سے روایت کی ہے: ایک اعرابی آیا اور مسجد میں داخل ہوا اور اپنا پردے کا مقام ننگا کر کے بول کرنے لگا تو لوگوں نے اس کو آواز دی یہاں تک کہ آوازیں بلند ہو گئیں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کو چھوڑ دو۔ لوگوں نے اس کو چھوڑ دیا اور اس نے پیشاب کیا، پھر آپ صلی اللہ علیہ وسلم نے پانی کے ڈول منگوا کر اس جگہ پر بہا دیئے۔","",{"k":"موطا (144)۔ اس میں تو مرسل ہے لیکن بخاری (221)۔ مسلم (284)۔ ترمذی (147)۔ نسائی (55)۔ احمد (12298)۔ دارمی (740)۔ میں متصل ہے۔","m":"فَصَاحَ ماضی واحد مذکر غائب، چلائے لوگ۔ عَلَا مضارع يَعْلُو ہے، آوازیں بلند ہوئیں۔ بِذَنُوبٍ ڈول جو پانی سے بھرا ہو۔"}],[386,"ام المومنین سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ ان کو ایک عورت نے کہا: میں اپنا ازار طویل رکھتی ہوں اور ناپاک جگہ پر گزرتی ہوں تو ام المومنین نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بعد والی زمین اس کو پاک کر دیتی ہے۔‘‘","",{"k":"ابوداود (383)۔ ترمذی (143)۔ ابن ماجہ (531)۔ احمد (26146)۔ مالک: 45۔ دارمی (742)۔ صحیح ہے۔ البانی: 369۔","m":"أُطِيلُ افعال سے مضارع معلوم واحد متکلم، لمبا ہے۔ ذَيْلِي اپنا دامن۔ أَمْشِي مضارع معلوم واحد متکلم، میں چلتی ہوں۔ اَلْقَذِرِ گندی، یا نجس جگہ۔ فَعِل کے وزن پر۔ يُطَهِّرُهُ تفعیل سے مضارع معلوم واحد مذکر غائب، اس جگہ کو پاک کرتا ہے۔","e":"اس سے ثابت ہوا گندی جگہ سے اگر کپڑا نجاست پر گر پڑے، اس میں عورت کا دامن، موزے، جوتے وغیرہ سب شامل ہیں اور وہ گندگی تر ہو، یا خشک ہو، اس کا وجود ہو یا وجود نہ ہو تو اسے دھونے کی ضرورت نہیں بلکہ بعد والی جگہ پر جو گرد و غبار ہے، یا مٹی ہے اس کو صاف کر دیتی ہے۔"}],[387,"بنو اشہل کی عورت سے مروی ہے: وہ کہتی ہے: میں نے عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! مسجد کی طرف کا ہمارا راستہ ناپاک ہے جب بارش ہو تو ہم کیا کریں؟ فرمایا: ’’اس کے بعد کا راستہ کیا صاف نہیں ہے؟‘‘ میں نے کہا: ہاں۔ فرمایا: ’’یہ اس کے بدلے ہے۔‘‘","",{"k":"ابوداؤد (384)۔ احمد (26904)۔ صحیح ہے۔ البانی: 370۔","m":"امْرَأَةٍ ایک انصاریہ عورت، ان کا نام نہیں بتایا گیا، یہ صحابیہ ہیں، ان کے نام کا معلوم نہ ہونا حدیث میں فرق نہیں ڈالتا، یہ حدیث صحیح ہے۔ (عون المعبود: ۱/۱۴۷) مُنْتِنَةٌ افعال سے اسم فاعل واحد مونث ہے، بد بودار، گندہ یا پلید۔ مُطِرْنَا ماضی مجہول جمع متکلم، جب ہم بارش برسائے جائیں۔ مِنْهَا اس رستہ سے۔ فَهَذِهِ، بِهَذِهِ یعنی پلید راستے کو صاف رستہ پاک بنا دیتا ہے۔ مسئلہ کی وضاحت اوپر والی حدیث میں گزر چکی ہے۔"}],[388,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص ناپاک جگہ پر جوتے پہن کر چلے تو مٹی جوتے کو پاک کر دیتی ہے۔‘‘ پاک کر دیتا ہے۔","",{"k":"ابوداؤد (385) صحیح ہے۔ البانی (371)","m":"وَطِئَ، عَلِمَ سے ماضی معلوم واحد مذکر غائب، روندے۔ لَهُ اس اذی یا گندگی کے لیے۔"}],[389,"اور ایک روایت میں ہے: ’’اگر کوئی شخص موزے پہن کر ناپاک جگہ پر چلے تو موزوں کے لیے مٹی پاک کرنے والی ہے۔‘‘","",{"k":"ابوداؤد (585) صحیح ہے۔ البانی (372)","m":"بِخُفَّيْهِ نون اضافت کی وجہ سے گر گیا ہے، یہ تثنیہ ہے، اپنے موزوں کے ساتھ۔ فَطَهُورُ پاکیزگی۔ هُمَا ان دونوں موزوں کی۔"}],[390,"سیدنا ابن عباس رضی اللہ عنہما نے کہا: اگر کپڑا ناپاک گارے پر پڑے یا تو ناپاک راستے پر چلے تو اپنے اس کپڑے اور جوتے وغیرہ کو دھو کر پاک کر دے اور گندگی خشک ہو تو تیرے اوپر کوئی حرج نہیں۔","",{"k":"رزین، اس کی سند کیسی ہے، شارح کو علم نہیں، صحیح احادیث میں یہ تفریق نہیں مل سکی۔","e":"حدیث نمبر ۳۸۸ اور ۳۸۹ دلالت کرتی ہیں کہ جب نجاست جوتے یا موزوں کو لگ جائے تو انہیں زمین پر ملنے یا زمین سے صاف کرنے سے ان کی پاکیزگی ثابت ہو جاتی ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ اس کی وضاحت میں فرماتے ہیں: یہ گندگی تر ہو یا خشک ہو، جسم رکھتی ہو یا جسم نہ رکھتی ہو، جیسا کہ پاخانہ ہے یا پیشاب ہے زمین پر ملنے سے صاف ہو جاتی ہے۔ (مرعاۃ: ۱/۵۶۴) اس کی تائید سیدنا ابوسعید خدری رضی اللہ عنہ سے لینے والی حدیث بھی کرتی ہے کہ ایک دفعہ رسول اکرم صلی اللہ علیہ وسلم نے اپنے صحابہ کرام رضی اللہ عنہم کو جوتوں سمیت نماز پڑھا رہے تھے، آپ نے جوتے اتار دیئے تو صحابہ کرام رضی اللہ عنہم نے بھی اتار دیئے۔ آپ نے فرمایا: میرے جوتوں میں تو گندگی تھی میں نے اس لیے اتارے تم نے کیوں اتارے؟ تو انہوں نے کہا کہ جب تک آپ نے نہ اتارے ہم نے بھی جوتے نہ اتارے، جب آپ نے اتار دئیے ہم نے آپ کی اتباع میں جوتے اتار دیئے تو اس وقت آپ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’جب تم میں سے کوئی مسجد کی جانب آئے تو دیکھ لے اگر جوتے میں گندگی لگی ہو تو اسے صاف کرے اور ان میں نماز پڑھ لے۔‘‘ (ابوداؤد، کتاب الصلاۃ، باب الصلاۃ فی النعل: ۱/۱۰۲) اس سے ان لوگوں کی بات کی تردید ہوئی ہے جو یہ کہتے ہیں کہ نجاست جب وجود والی ہو اور خشک ہو جائے تو وہ زمین پر ملنے سے صاف نہیں ہوتی، اسے دھونا چاہیے اور ان کی تردید بھی ہوتی ہے جو کہتے ہیں کہ نجاست کا وجود نہ ہو تو پھر ملنے سے پاک نہیں ہوتی، دھونے سے ہوتی ہے۔\nلیکن درج شدہ احادیث صحیحہ ان دونوں موقف کے خلاف یہ ثابت کر رہی ہیں جوتے یا موزے کو اگر نجاست لگ جائے، وہ گاڑھی ہو یا پتلی ہو، تر ہو یا خشک ہو تو زمین پر ملنے سے پاک ہو جاتی ہے۔ باقی رہی بات حدیث نمبر ۳۹۰ والی روایت میں نجاست کے تر ہونے یا خشک ہونے کی صورت میں صاف کرنے کی تفریق کا معاملہ یہ ایک قول ہے، صحیح احادیث کے مقابلہ میں اس پر عمل نہیں کیا جا سکتا، جبکہ اس کی سند کا بھی علم نہیں کیسی ہے۔"}],[391,"سیدہ عائشہ رضی اللہ عنہا نے کہا: میں خود رسول اللہ صلی اللہ علیہ وسلم کے کپڑے سے جنابت (منی) دھوتی تھی پھر آپ صلی اللہ علیہ وسلم نماز کے لیے جاتے اور پانی کا نشان کپڑے پر نمایاں ہوتا تھا۔","",{"k":"بخاری (229)۔ مسلم (290)۔ ترمذی (117)۔ نسائی (301)۔ ابوداؤد (373)۔ ابن ماجہ (539)۔ احمد (25863)۔","m":"بُقَعَ اس کا واحد بُقْعَۃ ہے، دو رنگوں کے اختلاف کو کہتے ہیں، یعنی کپڑا خشک ہوتا، اتنی جگہ تر ہوتی جہاں سے منی دھوئی ہوتی۔"}],[392,"اور ایک روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم منی کو دھویا کرتے تھے اور پھر نماز کی طرف اسی کپڑے میں تشریف لے جاتے اور میں دھونے کی جگہ میں دھلائی کا اثر دیکھتی تھی۔","",{"k":"مسلم (289)۔ بقیہ تخریج نمبر 391 والی ہے۔","m":"أَنْظُرُ، نَصَرَ سے مضارع معلوم واحد مذکر متکلم، میں دیکھ رہی ہوتی۔ أَثَرِ اس کی جمع آثَار ہے، نشانات۔ اَلْغَسْلِ دھونے۔"}],[393,"علقمہ اور اسود بیان کرتے ہیں کہ ایک مرد ام المومنین سیدہ عائشہ رضی اللہ عنہا کے ہاں مہمان تھا۔ اس نے صبح کو اپنے کپڑے دھوئے۔ ام المومنین رضی اللہ عنہا نے کہا تیرے لیے یہ کافی تھا کہ تو متاثرہ جگہ دھو دیتا اور اگر وہ چیز نظر نہ آتی تھی تو اس کے آس پاس پانی چھڑک دیتا۔ میں نے دیکھا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے کپڑے سے میں نے اچھی طرح منی کو کھرچ دیا اور آپ صلی اللہ علیہ وسلم نے اس میں نماز پڑھی۔","",{"k":"مسلم (288) بخاری (229) ترمذی (117) نسائی (301) ابوداؤد (373) ابن ماجہ (539) احمد (25863)","m":"فَأَصْبَحَ افعال سے ماضی واحد مذکر غائب، ہو گیا۔ يُجْزِئُكَ افعال سے مضارع معلوم واحد مذکر غائب، ضمیر مفعول یہ ہے، تجھے کافی ہے۔ رَأَيْتَهُ ماضی واحد مذکر حاضر ضمیر مفعول یہ ہے، منی کی طرف لوٹتی ہے، تو نے اسے دیکھا تھا، مَكَانَهُ اس منی کی جگہ۔ لَمْ تَرَ نفی جحد واحد مذکر مخاطب، نہ دیکھا تو نے۔ نَضَحْتَ ماضی واحد مذکر حاضر، تو پانی چھڑک دیتا۔ رَأَيْتُنِي ماضی واحد متکلم، نون وقایہ یا مفعول یہ، میں نے خود کو دیکھا۔ أَفْرُكُهُ، نَصَرَ مضارع معلوم واحد متکلم، میں منی کو مل دیتی کہ اس کا وجود ختم ہو جاتا۔"}],[394,"اسی کی روایت میں عبد اللہ بن شہاب خولانی سے منقول ہے کہ اس نے کہا: میں ام المومنین عائشہ رضی اللہ عنہا کے ہاں ٹھہرا۔ مجھے اپنے کپڑے میں احتلام ہوا تو میں نے کپڑے کو پانی میں ڈال کر دھویا پس ام المومنین کی ایک خادمہ نے دیکھا اور عائشہ رضی اللہ عنہا کو خبر دی۔ تو عائشہ رضی اللہ عنہا نے پیغام بھیجا کہ تجھے اپنے کپڑوں کے ساتھ یہ معاملہ کرنے پر کس چیز نے آمادہ کیا ہے؟ میں نے عرض کیا کہ میں نے وہ دیکھا جو سویا ہوا انسان دیکھتا ہے۔ تو انہوں نے کہا: کیا تو نے کپڑوں میں کچھ دیکھا ہے؟ میں نے کہا نہیں۔ انہوں نے کہا: اگر تو کچھ دیکھے تو اس کو دھو دے۔ میں نے آپ صلی اللہ علیہ وسلم کے کپڑے سے خشک منی اپنے ناخن سے کھرچی ہے۔","",{"k":"مسلم (290)۔ بخاری (229)۔ ترمذی (117)۔ نسائی (301)۔ ابوداؤد (373)۔ ابن ماجہ (539)۔ احمد (25863)۔","m":"فَاحْتَلَمْتُ افتعال سے ماضی معلوم، واحد مذکر متکلم، میں احتلام والا ہو گیا۔ ثَوْبَيَّ یہ تثنیہ ہے، اپنے دو کپڑوں میں۔ فَغَمَسْتُهُمَا، ضَرَبَ سے ماضی واحد متکلم، میں نے ان دونوں کپڑوں کو پانی میں ڈبو دیا۔ فَرَأَتْنِي واحد مونث غائب، مجھے دیکھا۔ فَأَخْبَرَتْهَا افعال سے ماضی واحد مونث، اس لونڈی نے سیدہ عائشہ رضی اللہ عنہا کو اطلاع دی۔ لَأَحُكُّهُ، نَصَرَ سے مضارع معلوم واحد متکلم، میں کھرچتی۔ يَابِساً یہ تمیز کی بنا پر منصوب ہے، یا حال ہے، خشک ہوتا۔ بِظُفُرِي اپنے ناخن کے ساتھ۔"}],[395,"ہمام رحمہ اللہ سے مروی ہے کہ وہ ام المومنین عائشہ رضی اللہ عنہا کے مہمان تھے اور احتلام ہوا پھر اس کی مثل روایت ہے۔","",{"k":"ابو داؤد (371)۔ صحیح ہے۔ البانی: 357۔"}],[396,"ہمام بن حارث کہتے ہیں کہ ام المومنین عائشہ رضی اللہ عنہا کے پاس ایک مہمان آیا تو انہوں نے مہمان کو زرد رنگ کا لحاف دینے کا حکم دیا اور وہ اس میں سویا اور اس کو احتلام ہوا پس حیاء کی وجہ سے احتلام کے اثر سمیت لحاف واپس کرنا مناسب نہ سمجھا بلکہ پانی میں ڈال کر پھر واپس کیا تو ام المومنین نے کہا اس مرد نے ہمارا کپڑا کس لیے خراب کر دیا اسے اتنا ہی کافی تھا کہ ناخن سے اس جگہ کو کھرچ دیتا میں خیال کرتی ہوں کہ میں نے خود رسول اللہ صلی اللہ علیہ وسلم کے کپڑے سے اپنی انگلیوں سے رگڑ کر منی کو صاف کیا ہے۔","",{"k":"ترمذی (116)۔ صحیح ہے۔ البانی (101) بقیہ 391 والی حدیث کی تخریج ہے۔","m":"ضَافَ ماضی واحد مذکر، مہمان ہوا۔ بِمِلْحَفَةٍ لحاف۔ فَاسْتَحْيَا استفعال سے ماضی واحد مذکر غائب، شرم کی۔ لِمَ کیوں۔ يَكْفِيهِ مضارع معلوم واحد مذکر غائب، اسے کافی تھا۔ بِأَصَابِعِي میری انگلیاں۔"}],[397,"یحییٰ بن عبد الرحمن بن حاطب راوی ہیں کہ سیدنا عمر رضی اللہ عنہ کو احتلام ہوا اور قافلے میں پانی نہیں تھا پس سوار ہو کر چل دیئے اور جب پانی پر پہنچے تو احتلام کا اثر کپڑے سے دھو کر صاف کر دیا۔ عمرو بن العاص رضی اللہ عنہ نے عرض کی: ہمارے پاس دوسرے کپڑے موجود ہیں۔ یہ کپڑا چھوڑ دو تا کہ دھو دیا جائے۔ تو عمر بن خطاب رضی اللہ عنہ نے کہا: ابن العاص تیرے اوپر تعجب ہے۔ اگر تجھے کپڑے میسر ہیں تو کیا سب لوگوں کو اسی طرح میسر ہیں؟ اللہ کی قسم! اگر میں ایسا کرتا تو ایک طریقہ قائم ہو جاتا ہے۔ بلکہ میں تو جو مجھے نظر آئے گا اس کو دھو دوں گا، جو میں نے نہ دیکھا اس پر پانی چھڑک دونگا۔‘‘ (الموطا)","",{"k":"مالك: 116۔","m":"أَسْفَرَ ماضی واحد مذکر غائب، خوب سفیدی کی۔ فَدَعْ امر ہے، چھوڑ دے۔ وَاعَجَبًا یہ منادی کے طور پر منصوب ہے، تعجب ہے، یہ اظہار درد کے لیے ہے۔ كُنْتَ واحد مذکر مخاطب، تو۔ لَمْ أَرَ نفی مضارع واحد متکلم، میں نے نہیں دیکھا۔"}],[398,"ابن عباس رضی اللہ عنہما کا قول ہے کہ منی بلغم کے حکم میں ہے پس اس کو اپنے سے دور کرے خواہ گھاس کے ساتھ سہی۔ (ترمذی تعلیقاً)","",{"m":"الْمُخَاطِ بلغم۔ فَأَمِطْهُ افعال سے امر واحد ضمیر مفعول بہ، اسے دور کر۔ بِإِذْخِرَةٍ ایک قسم کی خوشبودار گھاس ہے۔","e":"منی پاک ہے یا پلید ہے، اس بارے میں علمائے کرام کا اختلاف ہے۔ امام مالک اور ابوحنیفہ رحمہما اللہ کی رائے ہے کہ منی پلید ہے۔ علمائے کرام کی کثیر تعداد منی کے پاک ہونے کی قائل ہے، علی، سعد بن ابی وقاص، ابن عمر، عائشہ رضی اللہ عنہم شافعی اور دیگر اصحاب الحدیث کا یہ موقف ہے کہ یہ پاک ہے، جو اسے نجس قرار دیتے ہیں ان کی دلیل یہ ہے کہ اسے دھونے کا حکم آیا ہے اور جو اسے پاک قرار دیتے ہیں ان کی دلیل یہ ہے کہ اسے کھرچنے کا ذکر بھی آیا ہے اگر یہ پلید ہوتی تو صرف کھرچنے کی اجازت نہ آتی بلکہ اسے دھونے کا حکم آتا۔ راقم کا خیال ہے، دونوں طرف دلائل طاقتور ہیں، فیصلہ بہت مشکل ہے، لیکن علامہ عبدالرحمن مبارکپوری رحمہ اللہ فرماتے ہیں: فَالصَّوَابُ أَنَّ الْمَنِيَّ نَجَسٌ ’’درست یہ ہے کہ منی پلید ہے۔‘‘ (تحفۃ الاحوذی: ۱/۱۱۴) علامہ عبیداللہ رحمانی رحمہ اللہ فرماتے ہیں: منی پلید ہے لیکن ان احادیث میں اسے صاف کرنے کے مختلف طریقے بتائے گئے ہیں جو سب جائز ہیں، دھو کر، کھرچ کر، یا مل کر صاف ہو سکتی ہے۔ (مرعاۃ: ۱/۵۵۸)"}],[399,"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا سے مروی ہے کہ ایک عورت نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور عرض کیا: ہم میں سے کسی عورت کو جب حیض آئے اور کپڑے کے ساتھ لگے تو وہ کیا کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کو رگڑ دے پھر کھرچ کر پانی کے ساتھ صاف کرے اور پھر اس پر پانی ڈالے پھر اس میں نماز پڑھے۔‘‘","",{"k":"ترمذی (117)۔ صحیح ہے۔ (102) بخاری (229)۔ مسلم (289)۔ نسائی (295)۔ ابوداود (373)۔ ابن ماجہ (536)۔ احمد (24765)۔","m":"اِمْرَأَةٌ عورت۔ یہ خود سیدہ اسماء رضی اللہ عنہا ہی تھیں، اپنا نام انہوں نے پوشیدہ رکھا ہے۔ (فتح الباری: ۱/۳۳۱) قَحُتُّهُ مضارع معلوم واحد مؤنث غائب، اسے کھرچے کہ اس خون کا وجود نہ رہے۔ تَقْرُصُهُ، نَصَرَ سے واحد مؤنث غائب، پانی لگا کر انگلیوں کے کنارے سے خون کی جگہ ملے تا کہ کپڑے کے اندر سے اس خون کے ذرات خارج ہوں۔ تَنْضَحُهُ، مَنَعَ سے مضارع معلوم واحد مؤنث غائب، پانی کے چھینٹے مارے۔"}],[400,"ایک روایت ہے: ’’اگر کپڑے میں خون دیکھے تو پانی ڈال کر اس کو رگڑ کر صاف کر دے اور جس جگہ کچھ نظر نہ آتا ہو وہاں چھینٹے مارے اور اس میں نماز پڑھ لے۔‘‘","",{"k":"بخاری (227)۔ مسلم (291)۔ ترمذی (138)۔ نسائی (293)۔ ابوداود (361)۔ ابن ماجہ (629)۔ احمد (26441)۔ مالک: 136۔ دارمی (1016)۔ (400) ابوداود (360)۔ حسن صحیح ہے۔ (346) بخاری (307)۔ مسلم (291)۔ ترمذی (138)۔ آگے نمبر 399 والی تخریج۔","m":"رَأَتْ واحد مؤنث ماضی غائب، وہ عورت دیکھے فِيهِ اس کپڑے میں۔"}],[401,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ ہم میں سے کسی کو حیض آتا تو وہ اپنے کپڑے سے حیض کے بعد خون کھرچ دیتی، پھر دھوتی اور پھر سارے کپڑے پر پانی ڈالتی اور پھر اس میں نماز پڑھتی تھی۔ (بخاری)","",{"k":"بخاری (308)۔ ابوداود (361)۔ ابن ماجہ (630)۔","m":"تَقْتَرِصُ افتعال سے مضارع معلوم واحد مؤنث غائب، پانی سے مل کر صاف کرے۔ سَائِرِهِ سارے پر۔"}],[402,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں، ہم میں سے بعض خواتین کا ایک ہی لباس ہوتا تھا اور اسی میں اس کو حیض آتا اور کپڑے کو خون لگتا تو وہ تھوک لگا کر ناخن سے کھرچتی تھی۔","",{"k":"بخاری (312)۔ ابوداود (364)۔ دارمی (1009)۔","m":"أَصَابَهُ افعال سے ماضی واحد مذکر غائب، ضمیر مفعول بہ ہے، اس کپڑے کو لگ جائے۔ قَالَتْ واحد مؤنث غائب، کرتی۔ بِرِيقِهَا اپنے تھوک کے ساتھ۔ فَقَصَعَتْهُ واحد مؤنث غائب، اس خون کو کھرچتی۔ ایک نسخے میں مَصَعَتْهُ ہے معنی ایک ہی ہے۔"}],[403,"سیدہ معاذہ رضی اللہ عنہا سے روایت ہے کہ میں نے عائشہ رضی اللہ عنہا سے حائضہ کے بارے میں سوال کیا کہ اس کے کپڑے کو حیض کا خون لگ جائے تو کیا کرے؟ انہوں نے کہا کہ اس کو دھوئے اور اگر اس کا اثر نہ جائے تو زردی (ورس بوٹی یا زعفران) وغیرہ لے کر اس کو تبدیل کر دے۔","",{"k":"ابوداود (357)۔","m":"فَلْتُغَيِّرْهُ تفعیل سے واحد مؤنث غائب، چاہیے وہ عورت تبدیل کرے۔ صُفْرَةٍ زردی، مراد زعفران، یا ورس بوٹی ہے۔"}],[404,"سیدہ عائشہ رضی اللہ عنہا نے کہا: میں اور نبی کریم صلی اللہ علیہ وسلم ایک ہی چادر میں رات بسر کرتے تھے مجھے حیض آتا اور آپ صلی اللہ علیہ وسلم کے بدن مبارک سے لگ جاتا تو صرف اس جگہ کو دھوتے اور اس میں نماز پڑھتے تھے۔","",{"k":"نسائی (284)۔ ابوداود (269)۔ دارمی (995)۔ صحیح ہے۔ البانی: 273۔","m":"نَبِيتُ مضارع معلوم جمع متکلم، ہم رات گزارتے۔ الشِّعَارُ وہ لباس جو جسم کے ساتھ ملا ہو۔ طَامِثٌ حیض جو بن پر ہوتا۔ وَلَمْ يَعْدُهُ فی جحد واحد مذکر غائب، اس سے آگے نہ دھوتے۔ فِيهِ اس کپڑے میں۔"}],[405,"ام قیس بنت محصن رضی اللہ عنہا بیان کرتی ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے حیض کے خون کے بارے میں سوال کیا جو کپڑے کو لگتا ہے آپ صلی اللہ علیہ وسلم نے فرمایا: اس کو ٹیڑھی چیز کے ساتھ کھرچ کر پانی اور بیر کے پتوں سے دھو دے۔‘‘","",{"k":"نسائی (292)۔ ابوداود (263)۔ ابن ماجہ (628)۔ احمد (26461)۔ دارمی (1019)۔ صحیح ہے۔ البانی: 281۔","m":"حُكِّيهِ امر واحد مؤنث، تو اسے کھرچ۔ بِضِلَعٍ لکڑی کے ساتھ۔ وَاغْسِلِيهِ امر واحد مؤنث تو اسے دھو۔ سِدْرٍ بیری کے پتے۔","e":"ان تمام احادیث سے ثابت ہوتا ہے کہ حیض کا خون ناپاک ہے، اور تھوڑا لگا ہو یا زیادہ لگا ہوا سے صاف کرنا ضروری ہے۔ جو یہ کہتے ہیں کہ تھوڑی مقدار تقریباً ایک درہم کے برابر لگا ہو تو معاف ہے، اسے صاف کرنے کی ضرورت نہیں یہ احادیث اس کی تردید کرتی ہیں، تھوڑا ہو یا زیادہ ہوا سے صاف کرنا ہے۔ ۲۔ یہ ثابت ہوا کہ خون حیض لگ جائے تو اسے نہایت ہی گہرے انداز سے صاف کیا جائے، ہاتھ کو پانی لگا کر ملا جائے، پانی چھڑکا جائے، کسی سخت چیز سے اسے کھرچا جائے تاکہ خون کے اثرات کپڑے سے نکل جائیں، تاہم کسی کاٹ دار چیز سے خون کے اثرات دور کرنے کی ضرورت نہیں۔ ۳۔ خون حیض کو صاف کرنے کے لیے مٹی وغیرہ کفایت نہیں کرتی، اسے دور کرنے کے لیے پانی ضروری ہے اور یہ بھی ثابت ہوا کہ دیگر مائع چیزیں بھی اس نجاست کو دور نہیں کر سکتیں۔ فقط پانی ہی سے یہ پاک ہوتی ہے۔ خون حیض کو ناخن سے کھرچنا یا تھوک لگا کر صاف کرنا، یا ملنا وغیرہ کا یہ مطلب نہیں کہ فقط ان سے ہی یہ خون حیض صاف کیا تھا، پانی کے استعمال کی نفی نہیں ہوئی۔ ان کے استعمال کے بعد پانی بھی استعمال ہوتا تھا تا کہ اچھی طرح کپڑے سے اس کے اثرات زائل ہوں۔"}],[406,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کسی شخص کے برتن میں کتا پی جائے تو وہ اس کو سات بار دھوئے۔‘‘","",{"k":"نسائی (63)۔ صحیح ہے۔ البانی: 62۔ بخاری (172)۔ مسلم (279)۔ ترمذی (91)۔ ابوداود (73)۔ ابن ماجہ (364)۔ احمد (10217)۔ مالک: 67۔","m":"فَلْيَغْسِلْهُ امر غائب واحد مذکر، اسے دھونا چاہیے۔"}],[407,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کتا جب برتن میں منہ مار جائے تو اسے سات مرتبہ دھوؤ۔ پہلی بار مٹی کے ساتھ۔‘‘","",{"k":"مسلم (279)۔ کتاب الطہارۃ، بقیہ تخریج نمبر 406 والی ہے۔","m":"وَلَغَ یہ وَهَبَ يَهَبُ کے وزن پر ہے، زبان برتن میں داخل کرے پانی پیئے یا خالی زبان لگائے۔ أُولَاهُنَّ ان سات مرتبہ میں سے۔ طهور اناء احدکم مبتداء ہے، ان یغسلہ اس کی خبر ہے۔"}],[408,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: کتا جب برتن میں منہ مار جائے تو اسے سات بار دھوؤ، ساتویں مرتبہ مٹی کے ساتھ۔‘‘","",{"k":"ابوداود (73)۔ صحیح ہے۔ البانی: 66۔ یہ لفظ کہ ساتویں مرتبہ مٹی لگائیں یہ بات شاذ ہے۔ درست وہی ہے جو اوپر ہے کہ پہلی مرتبہ مٹی لگائی جائے۔ بقیہ تخریج اوپر بیان کر دی ہے۔"}],[409,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’سات مرتبہ دھوئے پہلی بار یا آخری بار مٹی کے ساتھ دھوئے۔ اور جب اس سے بلی پی جائے تو ایک بار دھوئے۔‘‘","",{"k":"ترمذی (91)۔ صحیح ہے۔ البانی: 79۔ بقیہ تخریج نمبر 406 والی ہے۔","m":"يُغْسَلُ مضارع مجهول واحد مذکر غائب، دھویا جائے۔ الْهِرَّةُ بلی۔"}],[410,"عبداللہ بن مغفل رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اس کو آٹھویں مرتبہ (مٹی سے مانجو)۔‘‘","",{"k":"مسلم (280)۔ ترمذی (1489)۔ نسائی (4288)۔ ابوداود (2845)۔ ابن ماجہ (3205)۔ احمد (20053)۔ دارمی (2008)۔","m":"وَعَفِّرُوهُ تفعیل سے امر حاضر، جمع مذکر، مانجو اسے۔ الثَّامِنَةَ آٹھویں مرتبہ۔","e":"۱۔ ان احادیث سے ثابت ہوتا ہے کہ جس برتن میں کتا منہ ڈالے وہ پلید ہو جاتا ہے، اسے دھونا ضروری ہے۔ ۲۔ اس کی وجہ یہ ہے کہ کتا اپنی دبر چاٹتا ہے، جس کے ذریعے اس کے منہ میں زہریلے جراثیم پیدا ہوتے ہیں، جب وہ کسی برتن میں منہ ڈالتا ہے تو وہ جراثیم برتن میں داخل ہو جاتے ہیں، انہیں دھوئے بغیر وہ برتن استعمال کیا جائے تو وہ جراثیم انسانی جسم میں چلے جاتے ہیں، جس سے معدے میں سوراخ ہو جاتے ہیں، پھیپھڑے وغیرہ کو نقصان بھی ہوتا ہے، کئی بیماریاں جنم لیتی ہیں، اس لیے برتن کو دھونے کا حکم ہے۔ ۳۔ یہ وجہ ہو یا نہ ہو ایک مسلمان کی حیثیت سے ہمارا فرض ہے کہ ہم کتاب وسنت کی رو سے جو کتے کے منہ ڈالنے سے ہمیں برتن دھونے کا حکم ملا ہے اس پر عمل کریں۔ جو چیز برتن میں ہوا سے گرا دیا جائے۔ (مرعاۃ: ۱/۵۵۳) ۴۔ ایک مکتب فکر کا خیال ہے کہ جس برتن میں کتا منہ ڈالے اسے تین مرتبہ دھویا جائے اور وہ مٹی سے مانجنا ضروری قرار نہیں دیتے۔ لیکن یہ احادیث اس موقف کی تردید کرتی ہیں کہ مٹی سے مانجا بھی جائے اور اس کے علاوہ سات مرتبہ دھویا بھی جائے۔ اب یہ وضاحت باقی ہے کہ سات مرتبہ دھویا جائے یہ تو ثابت ہوا اور مٹی سے مانجنا بھی ثابت ہے مگر روایات مختلف ہیں ایک میں آتا ہے کہ ان سات مرتبہ میں پہلی مرتبہ مٹی سے دھوئیں، ایک میں آتا ہے کہ ساتویں مرتبہ مٹی سے دھوئیں، ایک میں آتا ہے کہ پہلی مرتبہ یا آخری مرتبہ مٹی سے مانجھیں۔ ایک میں آتا ہے، سات مرتبہ دھوؤ اور آٹھویں مرتبہ مٹی سے مانجو۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: ان میں سے سب سے زیادہ راجح اور زیادہ محفوظ یہ لفظ ہے کہ ان سات مرتبہ میں سے پہلی مرتبہ مٹی سے دھوئیں اور ایک مرتبہ مٹی سے مانج کر اس برتن کو پانی سے دھوئیں اس کے علاوہ سات مرتبہ پانی سے مزید دھوئیں یہ کل آٹھ مرتبہ ہوا۔ یہ صحیح ترین طریقہ ہے، تمام احادیث کا یہی نتیجہ ہے۔ (مرعاۃ: ۱/۵۵۲)"}],[411,"حمزہ بن عبداللہ نے اپنے باپ سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں مسجد نبوی میں کتے آتے جاتے اور پیشاب کرتے تھے صحابہ اس پر پانی نہ چھڑکتے تھے۔","",{"k":"بخاری (174)۔ مسلم (2244)۔ ابوداؤد (2250)۔ احمد (10373)۔ مالک: 1729۔","m":"كَانَتْ واحد مونث غائب، فعل ناقص، تھے۔ الْكِلَابُ اس کا واحد الْكَلْبُ ہے، کتے۔ یہ فعل ناقص کا اسم ہے۔ تَقْبِلُ افعال سے مضارع معلوم واحد مونث غائب آتے۔ وَتُدْبِرُ افعال سے واحد مونث غائب مضارع معلوم جاتے۔ یہ عطف سے محل نصب پر ہیں، کیونکہ یہ فعل ناقص کی خبر ہیں۔ الْمَسْجِدِ اس میں الف لام عہدی ہے، مراد مسجد نبوی صلی اللہ علیہ وسلم ہے۔ يَرُشُّونَ مضارع معلوم جمع مذکر غائب، چھڑکتے نہ تھے۔ مِنْ ذلِكَ پیشاب کرنے یا آنے جانے سے۔"}],[412,"ابوداؤد میں اسی طرح ہے، اس میں یہ الفاظ ہیں: مسجد میں کتے آتے جاتے تھے اور پیشاب کرتے تھے۔","",{"k":"ابوداؤد (382)۔ صحیح ہے۔ البانی: 368۔ بخاری (174)۔ احمد (5366)۔","m":"تَبُولُ مضارع معلوم، واحد مونث غائب، پیشاب کرتے۔","e":"۱۔ یہ احادیث دلالت کرتی ہیں کہ کتے مسجد سے گزر جائیں تو مسجدوں کو دھونے کی ضرورت نہیں کیونکہ حدیث میں پانی کے چھینٹے مارنے کی نفی ہے تو دھونا تو بہت دور کی بات ہے، ہاں کوئی ظاہری نجاست لگی ہو مثلاً ان کے وجود پر پاخانہ وغیرہ کا وجود ہو تو اسے صاف کیا جائے۔ کتے کے آنے یا پیشاب کرنے سے مسجد دھونے کی ضرورت نہیں۔ وجہ یہ ہے کہ زمین دھوپ یا ہوا کی وجہ سے خشک ہو جائے تو وہ پاک ہو جاتی ہے، نجاست کے اثرات اس سے دور ہو جاتے ہیں۔ بعض حضرات کہتے ہیں کہ اس حدیث میں جو یہ لفظ آتا ہے کہ کتے پیشاب بھی کرتے تھے، یہ محفوظ نہیں، یہ بات درست نہیں۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: فَالظَّاهِرُ أَنَّ هَذِهِ اللَّفْظَةَ مَحْفُوظَةٌ ’’یہ بات بالکل عیاں ہے کہ یہ لفظ محفوظ ہے۔‘‘ (مرعاۃ: ۱/۵۷۳) پھر اس کی غلط تاویل کی جاتی ہے کہ اگر یہ ثابت ہیں تو کتے اپنی جگہ پر باہر پیشاب کرتے تھے پھر آتے تھے، لیکن یہ تاویل بھی حدیث سے ٹکراتی ہے، حدیث میں تو صاف آتا ہے کہ مسجد میں پیشاب کر دیتے تھے۔ ان تاویل سازوں سے کہا جا سکتا ہے کہ پھر یوں کہو کہ کتے بہت سمجھدار تھے، پیشاب باہر کرتے پھر استنجاء کرتے پھر مسجد میں آتے، بات سیدھی سادی ہے اگر کوئی پیشاب وغیرہ کرتے بھی تو وہ دھوپ یا ہوا سے خشک ہو جاتا تھا۔ ایک غلط فہمی کا ازالہ آخر میں ضروری ہے کہ اس حدیث سے یہ ذہن میں کھٹکا پیدا ہوتا ہے کہ شاید صحابہ کرام رضی اللہ عنہم بھی اس میں لا پروائی رکھتے تھے کہ مسجد میں کتوں کا عام آنا جانا تھا، یہ بات نہیں، ایسا کبھی ہوتا تھا، کیونکہ اس وقت مسجد نبوی پر دروازہ نہ ہوتا تھا، جو ان کے آنے کو روکے، اگر دروازہ ہو بھی تو کبھی کبھار کسی طرح آ ہی جاتے ہیں، یہ نہیں کہ کتے مسجد میں تانتا ہی باندھے رکھتے تھے۔ (خطابی، بحوالہ مرعاۃ: ۱/۵۷۳)"}],[413,"کبشہ بنت کعب بن مالک سے روایت ہے، وہ ابوقتادہ کے بیٹے کے عقد میں تھیں، وہ کہتی ہیں کہ ابو قتادہ رضی اللہ عنہ میرے پاس آئے تو میں نے ان کو وضو کے لیے پانی ڈال کر دیا۔ بلی آئی اور اس میں پینے لگی تو ابو قتادہ رضی اللہ عنہ نے برتن بلی کے آگے جھکا دیا اور بلی نے پانی پیا۔ انہوں نے دیکھا کہ میں بغور ان کی طرف دیکھ رہی ہوں تو انہوں نے کہا: میرے چچا زاد بھائی کی بیٹی! کیا تجھے تعجب آ رہا ہے؟ میں نے کہا: ہاں۔ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’یہ ناپاک نہیں ہے یقیناً یہ تمہارے پاس آنے جانے والوں اور آنے جانے والی چیزوں میں سے ہے۔‘‘ (موطا اور اصحاب سنن)","",{"k":"ترمذی (92)۔ نسائی (68)۔ ابوداؤد (75)۔ ابن ماجہ (367)۔ احمد (22130)۔ مالک: 44۔ دارمی (736)۔ صحیح ہے۔ البانی: 80۔","m":"كَبْشَةُ بنت کعب بن مالک، ثابت ہے کہ یہ صحابیہ تھیں۔ (لسان المیزان: ۶/۸۶۰) یہ عبداللہ بن ابی قتادہ تابعی کی اہلیہ تھیں۔ دَخَلَ عَلَيْهَا اس کبشہ کے پاس آئے، یہ چونکہ بہو تھیں۔ فَسَكَبْتُ ماضی واحد متکلم، میں نے ڈالا ایک صورت واحد مونث بھی ہو سکتی ہے۔ اس کبشہ نے پانی ڈالا۔ وَضُوءًا وضو کا پانی۔ أَصْغَى افعال سے ماضی واحد مذکر غائب، مائل کر دیا۔ لَهَا اس بلی کے لیے۔ فَرَآنِي ماضی واحد مذکر غائب، نون وقایہ، یا مفعول بہ، پس مجھے دیکھا، ابو قتادہ نے۔ أَنْظُرُ مضارع معلوم واحد متکلم، میں دیکھتا ہوں، یہ حال بنتا ہے۔ أَتَعْجَبِينَ ہمزہ استفہام ہے، مضارع معلوم واحد مونث حاضر کیا تو تعجب کرتی ہے۔ يَا ابْنَةَ أَخِي اے میرے بھائی کی بیٹی، یہ محاورتاً کہا ہے۔ نَعَمْ ہاں میں تعجب کرتی ہوں۔ إِنَّهَا یہ بلی۔ بِنَجَسٍ مشائخ نے زیادہ تر بِنَجَسٍ جیم کے کسرہ کے ساتھ قرار دیا ہے۔ تا نہیں آئی یہاں هِرَّةُ کی جگہ سِنَّوْرُ (بلی) کا لفظ ہے جس میں تاء کی ضرورت نہیں۔ (نووی شرح مسلم) إِنَّهَا یہ بلی۔ یہ علت بیان کرنے کے لیے آیا ہے۔ اَلطَّوَّافِينَ او الطَّوَّافَاتِ نر اور مادہ دونوں کو جمع کیا گیا ہے۔ اور واؤ نون سے جمع آئی ہے جو کہ ذوی العقول کے لیے آتی ہے جبکہ یہ غیر ذوی العقول ہیں۔ دراصل ان بلیوں اور بلوں کو بھی ان خادموں اور انسانوں کے قائمقام قرار دے دیا ہے اس لیے ذوی العقول والی جمع ہے، یہ ان کے پاک ہونے کی وجہ ہے کہ گردش کرتے رہتے ہیں۔"}],[414,"سیدہ عائشہ رضی اللہ عنہا سے مثل اس کے مروی ہے اور وہ یہ کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بلی کے جوٹھے پانی سے وضو کرتے دیکھا ہے۔","",{"k":"ابوداؤد (76)۔ ابن ماجہ (368)۔ صحیح ہے۔ البانی: 69۔","m":"بِفَضْلِهَا اس بلی کے باقی بچے پانی سے۔"}],[415,"سیدہ عائشہ رضی اللہ عنہا نے کہا: نبی کریم صلی اللہ علیہ وسلم کے پاس سے بلی گزرتی تو آپ صلی اللہ علیہ وسلم اس کی طرف برتن جھکا دیتے تھے وہ اس سے پانی پیتی اور پھر آپ صلی اللہ علیہ وسلم اسی سے وضو کرتے تھے۔","",{"k":"طبرانی اوسط، بزار، رجالہ موثقون اصغاء الاناء لھا کے الفاظ چھوڑ کر ابوداؤد نے بھی بیان کی ہے۔ ہیثمی: 1085۔","m":"يَمُرُّ مضارع واحد مذکر غائب، گزرتا ہے۔ الْهِرُّ بلا۔","e":"ان احادیث میں یہ واضح طور پر بیان ہوا ہے کہ بلی کا وجود پاک ہے، اس کا جوٹھا بھی پاک ہے، اس کے جوٹھے سے بچے ہوئے پانی سے وضو کرنا جائز ہے اور اسے پینا بھی جائز ہے، اور ایک جگہ اوپر گزرا ہے کہ بلی منہ ڈالے تو برتن ایک دفعہ دھوؤ۔ یہ پلید ہونے کی وجہ سے نہیں یہ تو طبیعت کا شک دور کرنے کی وجہ سے کہا گیا ہے، بلی کے برتن میں منہ ڈالنے سے برتن پلید نہیں ہوتا، صفائی کے لیے دھونا ہو تو کوئی حرج نہیں۔ جو یہ کہتے ہیں کہ بلی کا جوٹھا مکروہ ہے، اُن کا موقف بالکل غلط ہے، یہ حدیث اس موقف کی تردید کرتی ہے۔"}],[416,"سیدہ میمونہ رضی اللہ عنہا نے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے گھی میں گرے پڑے چوہے کے متعلق سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس کو اس کے آس پاس کے گھی کو پھینک دو۔ بقیہ اپنا گھی کھاؤ۔‘‘","",{"k":"بخاری (235)۔ ترمذی (1798)۔ نسائی (4260)۔ ابوداؤد (3842)۔ احمد (26307)۔ مالک: 1815۔ دارمی (2085)۔","m":"سُئِلَ ماضی مجہول واحد مذکر غائب، سوال کیا گیا۔ سوال خود سیدہ میمونہ رضی اللہ عنہا نے ہی کیا تھا۔ فَأْرَةٍ چوہیا۔ سَقَطَتْ واحد مونث ماضی، گر پڑے۔ سَمَنٍ گھی۔ أَلْقُوهَا افعال سے امر حاضر جمع مذکر ضمیر مفعول یہ ہے، چوہیا کی جانب لوٹتی ہے، اس کو پھینک دو۔ وَمَا اور جو حَوْلَهَا اس چوہیا کے گرنے کے ارد گرد ہے۔ فَاطْرَحُوهُ امر جمع مذکر حاضر، وہ گھی بھی پھینک دو۔ وَكُلُوا امر حاضر جمع مذکر، کھاؤ۔"}],[417,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر گھی جامد ہو تو اس کو اور اس کے ارد گرد کو پھینک دو اور اگر پگھلا ہو تو اس کے قریب نہ جاؤ۔‘‘","",{"k":"ابوداؤد (3842)۔ بقیہ اوپر والی تخریج شاذ ہے۔ البانی: 827۔","m":"جَامِدًا جما ہوا۔ مَائِعًا پگھلا ہوا۔ فَلَا تَقْرَبُوهُ نہی جمع مذکر مذکر، اس کے قریب نہ جاؤ۔"}],[418,"سیدنا ابو درداء رضی اللہ عنہ راوی ہیں کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا کہ چوہا شوربے میں گر جاتا ہے۔ فرمایا: ’’اس کو نکال دو اور دو اور تین چلو آس پاس سے نکال کر بقیہ کو کھا لو۔‘‘ (الکبیر بسند ضعیف)","",{"k":"طبرانی اوسط، اس میں مسلمہ بن علی خشنی ہے، جو کہ سخت ضعیف ہے۔"}],[419,"سیدنا ابن عمر رضی اللہ عنہ سے مرفوعاً منقول ہے: اگر مائع ہو تو اس سے کوئی فائدہ اٹھاؤ۔","",{"k":"طبرانی اوسط، اس میں عبدالجبار بن عمر ہے، محمد بن سعد نے اسے ثقہ کہا ہے لیکن محدثین کی جماعت نے اسے ضعیف قرار دیا ہے۔ ہیثمی: 1592۔","e":"اس سے ثابت ہوتا ہے کہ گھی ہو یا اس طرح کی کوئی بھی چیز ہو اس میں چوہیا گر جائے، زندہ ہو یا مر جائے تو اسے اس چیز سے باہر پھینک دیا جائے اور اندازے سے جہاں وہ چوہیا گری ہے وہاں سے وہ چیز بھی پھینک دی جائے۔ باقیماندہ استعمال کر لی جائے، وہ پاک ہے۔ اور یہ جو آیا ہے کہ اس چیز سے تین چلو بھر لیے جائیں باقی استعمال کر لی جائے یہ قول ضعیف ہے، قابل حجت نہیں۔ نیز جامد یا غیر جامد کا جو فرق کیا گیا ہے، وہ مرفوع نہیں یہ سیدنا ابن عمر رضی اللہ عنہ کا قول ہے۔ (فتح الباری: ۹/۶۶۹) اس لیے جامد یا غیر جامد میں فرق ضروری نہیں اگر کوئی وضاحت کے طور پر صحابی رضی اللہ عنہ کی بات پر عمل کرنا ہے تو اس کی ہم تردید نہیں کرتے کیونکہ صحابی کی وضاحت ہے، ہم سے بہتر تھے۔ لیکن نبی صلی اللہ علیہ وسلم سے جامد چیز یا غیر جامد میں چوہیا گرے اسے نکال کر اور اردگرد سے کچھ پھینک کر دوسری چیز استعمال کرنا جائز ثابت ہوتی ہے یہی حجت ہے۔ ہاں چوہیا کے گرنے سے اس چیز کا رنگ، بو، ذائقہ تبدیل نہ ہوا ہو۔ اگر یہ تبدیل ہوا ہوگا تو پھر وہ چیز استعمال کرنا جائز نہیں۔"}],[420,"سیدنا انس رضی اللہ عنہ سے مروی ہے: رسول اللہ صلی اللہ علیہ وسلم سے گوندھے ہوئے آٹے میں خون کے قطرے پڑنے کے بارے میں سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے اس کے کھانے سے منع فرمایا۔","",{"k":"طبرانی اوسط، اس میں سوید بن عبد العزیز کو دحیم نے ثقہ کہا ہے۔ لیکن محدثین کی دوسری جماعت نے اسے ضعیف قرار دیا ہے، تو یہ روایت حجت نہ ہوئی۔"}],[421,"سیدنا ابو سعید خدری رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ایک لڑکے کے قریب سے گذرے جب کہ وہ بکری کی کھال اتار رہا تھا اور اچھی طرح اُتارنا نہیں جانتا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تو پیچھے ہو جاتا کہ میں تجھے طریقہ بتاؤں۔ پس آپ صلی اللہ علیہ وسلم نے بکری کی کھال اور گوشت کے درمیان ہاتھ ڈالا اور گوشت اور کھال جدا کرتے گئے یہاں تک کہ ہاتھ مبارک بغل تک چھپ گیا پھر آپ صلی اللہ علیہ وسلم تشریف لے گئے۔ لوگوں کو نماز پڑھائی اور وضو نہیں کیا۔ (ابوداؤد)","",{"k":"ابوداؤد (185)۔ ابن ماجہ (3179)۔ صحیح ہے۔ البانی: 170۔","m":"يَسْلُخُ، نَصَرَ سے مضارع معلوم واحد مذکر غائب، بکری کی کھال اتار رہا تھا۔ تَنَحَّ، تَفَعَّلَ سے امر حاضر ہے۔ واحد مذکر، ادھر ہٹو۔ أُرِيكَ افعال سے مضارع معلوم واحد متکلم ضمیر مخاطب مفعول بہ ہے۔\nمیں تجھے سکھاؤں۔ فَأَدْخَلَ افعال سے ماضی واحد غائب، داخل کیا نبی صلی اللہ علیہ وسلم نے اپنا ہاتھ۔ فَدَحَسَ ماضی واحد مذکر غائب، ہاتھ چھڑے کے اندر گھس گیا۔ تَوَارَثَ تفاعل سے ماضی واحد مؤنث غائب، چھپ گیا۔ الْاِبْطِ اس کی جمع آباط ہے، بغل تک۔ مَضَی اس کا مضارع يَمْضِی ہے، واحد مذکر غائب، پھر گزر گئے۔","e":"اس سے ثابت ہوا کہ حلال جانور کے گوشت پوست کو جو کہ کچے ہوں پختہ نہ بھی ہوں، ہاتھ لگ جائے نہ تو وضو ٹوٹتا ہے، نہ ہاتھ دھونا ضروری ہے، یہ پاک ہے، پلید نہیں۔ نیز معلوم ہوا کہ نبی اکرم صلی اللہ علیہ وسلم نہایت ہی سادہ طبیعت اور منکسر المزاج تھے غلاموں کا ہاتھ بٹاتے تھے۔"}],[422,"سیدنا ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’جب کچا چمڑا دباغت کیا جائے تو وہ پاک ہو جاتا ہے۔‘‘","",{"k":"مسلم (366)، کتاب الحیض ترمذی (1728)، نسائی (4242)، ابوداؤد (4123)، ابن ماجہ (3609)۔ احمد (3188)۔ مالک: 1079، دارمی (1986)۔","m":"دُبِغَ، نَصَرَ سے ماضی مجہول واحد مذکر غائب، رنگا جائے۔ الْاِهَابُ وہ چمڑا جو ابھی نہ رنگا گیا ہو۔ طَهُرَ ماضی واحد مذکر غائب، پاک ہوا۔"}],[423,"یزید بن ابی حبیب سے روایت ہے کہ ابوالخیر نے اس سے بیان کیا کہ میں نے علی بن وعلہ سبئی کو پوستین پہنے دیکھا تو اس کو ہاتھ لگایا: اس نے کہا تجھے کیا خیال ہے کہ تو نے اس کو ہاتھ لگایا ہے؟ میں نے ابن عباس رضی اللہ عنہما سے سوال کیا کہ ہم مغرب میں رہتے ہیں اور ہمارے ساتھ اقوام بربر اور مجوس رہتے ہیں اور وہ ذبح کیا ہوا بکرا لاتے ہیں اور ہم ان کا ذبیحہ نہیں کھاتے۔ اور وہ مشکیزے لاتے ہیں اور اس میں چربی ڈالتے ہیں۔ پس ابن عباس رضی اللہ عنہما نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے متعلق سوال کیا تھا پس آپ صلی اللہ علیہ وسلم نے فرمایا: ’’چمڑے کی دباغت اس کو پاک کر دیتی ہے۔‘‘","",{"k":"مسلم (366)، کتاب الحیض بقیہ تخریج نمبر 422 والی ہے۔","m":"فَوْرًا چڑا۔ فَمَسِسْتُهُ، عَلِمَ سے ماضی واحد متکلم، میں نے اسے چھوا۔ الْبَرْبَرُ ایک قوم ہے۔ وَالْمَجُوسُ آتش پرست قوم۔ نُؤْتَى، آتِی، يَأْتِی سے مضارع مجہول جمع متکلم، ہم لائے جاتے ہیں۔ بِالْكَبْشِ اس کی جمع اَكْبَاشٌ ہے، مینڈھا۔ ذَبَائِحَهُمْ اس کا واحد ذَبِيحَةٌ ہے، ذبح کیے ہوئے جانور۔ وَيَأْتُونَا مضارع معلوم جمع مذکر، یہ ہمارے پاس آتے ہیں۔ یا السِّقَاءِ اس کی جمع اسقیہ ہے، مشک یا پانی پینے کا برتن۔ اَلْوَدَكَ چربی۔"}],[424,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر کچا چمڑہ جب پکایا جائے تو وہ پاک ہو جاتا ہے۔‘‘","",{"k":"نسائی (4241)۔ صحیح ہے۔ البانی: 3955۔ بقیہ اوپر والی ہی تخریج ہے۔","m":"أَيْمَا جونا۔"}],[425,"سیدنا ابن عباس سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کا مری پڑی بکری کے پاس سے گذر ہوا تو فرمایا: تم نے اس کی کچی کھال سے فائدہ کیوں نہ اٹھایا؟ لوگوں نے عرض کی یہ مردار ہے۔ فرمایا: ’’حرام تو اس کا کھانا ہے۔‘‘ (بخاری ومسلم)","",{"k":"بخاری (5531)۔ مسلم (363)۔ ترمذی (1727)، نسائی (4235)، ابوداؤد (4110)، ابن ماجہ (3610)، احمد (1898)، مالک: 1078، دارمی (1988)۔","m":"هَلَّا یہ کلمہ تخصیص ہے، ترغیب کے لیے آتا ہے، کیوں نہیں۔ اسْتَمْتَعْتُمْ استفعال سے ماضی جمع مذکر غائب، تم نے فائدہ اٹھایا۔ اِنَّهَا یہ بکری۔ حَرُمَ ماضی واحد مذکر غائب، ایک نسخہ میں مجہول بھی ہے، حرام ہے۔"}],[426,"سیدنا ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ ایک بکری مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے مالک سے فرمایا: ’’تم نے اس کی کھال کیوں نہیں اتاری؟ تم اسے دباغت دے کر استعمال کر لیتے۔‘‘","",{"k":"ترمذی (1727)۔ صحیح ہے۔ البانی: 1411۔ بخاری (1492)، مسلم (363)۔ نسائی (4242)، ابوداؤد (4123)، ابن ماجہ (3909)، احمد (3511)، مالک: 1079، دارمی (1988)۔","m":"أَلَا کیوں نہیں۔ نَزَعْتُمْ ماضی جمع مذکر حاضر، تم نے اتارا۔ دَبَغْتُمُوهُ ماضی جمع مذکر حاضر ضمیر جلد کی جانب لوٹتی ہے، تم اسے رنگ لیتے۔"}],[427,"ابوداؤد میں اس کے مثل ہے اور اس میں یہ بھی مذکورہ ہے کہ زہری نے دباغت کی قید ذکر نہیں کی بلکہ جس حالت میں بھی ہو چمڑے سے فائدہ اٹھایا جائے جب وہ دباغت کیا جائے۔","",{"k":"ابوداؤد (4120)۔ صحیح ہے۔ البانی: 3470۔ بخاری (5532)۔ مسلم (366)۔ نسائی (4342)، ترمذی (1727)، ابن ماجہ (93610)، احمد (26312)، مالک: 1079، دارمی (1988)۔"}],[428,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے: نبی کریم صلی اللہ علیہ وسلم نے حکم دیا کہ کھال سے فائدہ اٹھایا جائے جب وہ دباغت کیا جائے۔","",{"k":"ابوداؤد (4124)، ضعیف ہے۔ نسائی (4252)، ابن ماجہ (3612)، احمد (24688)، مالک: 1080، دارمی (1987)۔"}],[429,"سیدہ عائشہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم سے مردار کی کھال کے بارہ میں سوال کیا گیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ رنگنے سے پاک ہو جاتی ہے۔‘‘","",{"m":"ذَكَاتُهَا اس کا پاک کرنا ہے، یعنی رنگنے سے پاک ہو جاتا ہے۔"}],[430,"رسول اللہ صلی اللہ علیہ وسلم نے اپنی وفات سے ایک ماہ پہلے قبیلہ جہینہ کی طرف چٹھی ارسال فرمائی کہ مردار کی کھال اور پٹھوں سے فائدہ نہ اُٹھاؤ۔","",{"k":"ابواداؤد: 4128، ترمذی (1729)، ابن ماجہ (3613)، احمد (18308)۔ نسائی (4249)۔ صحیح ہے۔ (3476)","m":"لَا تَنْتَفِعُوا افتعال نہی جمع مذکر حاضر، نفع نہ اٹھاؤ۔ وَلَا عَصَبٍ حیوان کے جوڑوں کے لیے پٹھے۔"}],[431,"عبداللہ بن عکیم کی دوسری روایت میں ہے کہ نبی کریم صلی اللہ علیہ وسلم کا خط ہمارے پاس آپ کی وفات سے دو ماہ پہلے پہنچا۔","",{"k":"ترمذی (1729)، ابوداؤد (4127)، ابن ماجہ (3613)۔ صحیح ہے۔ البانی: 1413۔","e":"ان تمام احادیث سے ثابت ہوا کہ ہر وہ مردہ جانور جس کا گوشت کھانا حلال ہے، اس کا چمڑا رنگ لینے سے پاک ہو جاتا ہے، اور وہ جانور جس کا گوشت نہیں کھایا جاتا اس کا چمڑا بھی رنگنے کے بعد پاک ہو جاتا ہے۔ البتہ خنزیر اور کتے کا چمڑا رنگنے سے بھی پاک نہیں ہوتا کیونکہ یہ دونوں جانور نجس ہیں۔ اور جب حلال جانور خود ذبح کیا ہو اس کا چمڑا رنگنے سے پہلے اور بعد دونوں صورتوں میں پاک ہے۔ ۲۔ یہ بھی ثابت ہوا کہ مردار کا چمڑا رنگنے کے بعد اس سے فائدہ اٹھانا جائز ہے۔ یعنی اس کی تجارت کرنا یا اسے استعمال کرنا رنگنے کے بعد جائز ہے، اس سے پہلے جائز نہیں۔ ۳۔ مردار کھانا حرام ہے۔ اس کا چمڑا رنگنے کے بعد اس کی مشک سے وضو کرنے اور اس پر نماز پڑھنے میں کوئی حرج نہیں۔ ۴۔ اور یہ جو روایت مذکور ہوئی ہے کہ نبی صلی اللہ علیہ وسلم نے اپنی وفات سے ایک ماہ یا دو ماہ پہلے مردار کے چمڑے سے فائدہ اٹھانے کی ممانعت کر دی تھی۔ یہ روایت مضطرب ہے، اور مرسل ہے کیونکہ عبداللہ بن عکیم نے نبی اکرم صلی اللہ علیہ وسلم سے نہیں سنا اور نہ عبدالرحمن بن ابی لیلیٰ نے عبداللہ بن عکیم سے سنا ہے۔ اگر بالفرض اس کی سند کی اس کمزوری کو صرف نظر بھی کر دیں تو ممانعت جو وارد ہوئی ہے۔ اس میں رنگنے سے، چمڑے سے فائدہ اٹھانے کی ممانعت ہے۔ فائدہ تب اٹھانا ہے جب چمڑا رنگا جائے اس وضاحت سے ٹکراؤ ختم ہو جاتا ہے، اور مسئلہ واضح ہوتا ہے کہ مردار کا چمڑا رنگنے سے پہلے استعمال نہ کیا جائے، رنگنے کے بعد استعمال کیا جائے۔ (عون المعبود: ۱/۱۱۴) مسئلہ: وہ جانور جس کا گوشت کھایا جاتا ہے، مردار ہونے کی وجہ سے اس کا گوشت کھانا تو حرام ہے لیکن اس کے بال، دانت اور سینگ وغیرہ پلید نہیں ہوتے، ان سے فائدہ اٹھایا جا سکتا ہے اور ہاتھی دانت کی تجارت بھی جائز ہے۔ (مرعاۃ: ۱/۵۶۲)"}],[432,"سیدنا اسامہ بن زید رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے درندوں کی کھال سے منع فرمایا ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (4132)، ترمذی (1771)، نسائی (4253)، احمد (20189)، دارمی (1983)، صحیح، البانی: 3480۔","m":"جُلُودِ اس کا واحد جِلْدٌ ہے، چھڑے۔ السِّبَاعِ اس کا واحد سَبُعٌ ہے، درندے۔","e":"درندوں کے چمڑے کا استعمال اس لیے منع ہے کہ اس میں فضول خرچی، عیش پسندی، خود پسندی ہے اور متکبروں کی عادت جھلکتی ہے۔"}],[433,"حسن سے مروی ہے کہ عمر رضی اللہ عنہ نے حج تمتع سے منع کرنے کا ارادہ کیا تو ابی رضی اللہ عنہ نے ان کو کہا کہ آپ یہ نہیں کر سکتے ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج تمتع کیا ہے اور عمر رضی اللہ عنہ نے یمنی چادروں کا لباس پہننا ممنوع قرار دینا چاہا اس لیے کہ ان کو پیشاب کے ساتھ رنگین بنایا جاتا ہے تو ابی رضی اللہ عنہ نے کہا: آپ ایسا نہیں کر سکتے کیونکہ نبی صلی اللہ علیہ وسلم نے بھی یمنی چادر زیب تن فرمائی ہے اور ہم نے بھی آپ صلی اللہ علیہ وسلم کے عہد مبارک میں پہنی ہے۔ (حسن بصری رحمہ اللہ نے عمر رضی اللہ عنہ سے سماعت کی ہے نہ ابی رضی اللہ عنہ سے۔)","",{"k":"احمد (20776)۔"}],[434,"سیدنا سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اپنے صحن صاف رکھا کرو یہودی لوگ اپنے صحن صاف نہیں رکھتے ہیں۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط طبرانی کے شیخ ثقہ نہیں باقی راوی صحیح کے راوی ہیں۔"}],[435,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بطور ردیف ایک گدھے پر سوار تھا جس کو یعفور کہتے تھے۔ مجھے پسینہ آیا تو آپ نے مجھے غسل کرنے کا حکم دیا۔ (الکبیر بسند ضعف)","",{"k":"طبرانی کبیر: 12648۔ ضحاک راوی کو احمد، یحییٰ، ابوزرعہ نے تو ثقہ کہا ہے، ان کے علاوہ دیگر محدثین نے انہیں ضعیف قرار دیا ہے۔ نبی کریم صلی اللہ علیہ وسلم سے ثابت ہے کہ آپ نے گدھے پر سواری کی، قرآن پاک میں بھی ہے: وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً. (النحل: 8) ”اس نے گھوڑے، خچر اور گدھے پیدا کیے تاکہ تم اس پر سوار ہو اور یہ زینت ہیں۔ اس سے ثابت ہوا گدھے کی سواری سے غسل والی بات درست نہیں۔"}],[436,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی وہ کہتے ہیں کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے حسین رضی اللہ عنہ بن علی رضی اللہ عنہ کو اپنی گردن پر اٹھایا ہوا تھا اور حسین رضی اللہ عنہ کا لعاب آپ صلی اللہ علیہ وسلم پر گر رہا تھا۔","",{"k":"ابن ماجہ (658)، احمد (9487)، صحیح ہے۔ البانی: 360536۔","m":"عَاتِقِہ اپنے کندھے پر وَ لُعَابَہ سیدنا حسین رضی اللہ عنہ کا لعاب۔ يَسِيلُ مضارع معلوم واحد مذکر غائب، بہہ رہے تھے۔ عَلَيْهِ آپ صلی اللہ علیہ وسلم پر۔","e":"اس سے ثابت ہوا کہ انسان کا لعاب یا کسی بھی حلال جانور کا لعاب پلید نہیں، اسے دھونے کی ضرورت نہیں۔ اگر صفائی کے لیے دھوئے تو کوئی حرج نہیں، تاہم وہ پاک ہے پلید نہیں۔ (۲) بچے کو کندھے پر بٹھانا، اسے اٹھانا اور پیار کرنا یہ بھی سنت ہے۔"}],[437,"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ میں ایک دن نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھا، آپ صلی اللہ علیہ وسلم نے پیشاب کرنا چاہا تو دیوار کے نیچے ایک گڑھے پر گئے اور پیشاب کیا اور پھر فرمایا جب تم میں سے کوئی پیشاب کرنا چاہے تو وہ اس کے لیے نرم جگہ تلاش کر لیا کرے۔ (ابوداؤد)","",{"k":"ابوداؤد (3)۔ احمد (19043)۔ ضعیف ہے۔ البانی: 1۔","m":"دَمِثًا نرم زمین جس میں پیشاب جذب ہو جائے۔ أَصْلِ بنیاد۔ جِدَارٍ دیوار۔ فَلْيَرْتَدْ افتعال سے امر غائب، چاہیے کہ وہ تلاش کرے۔","e":"اس حدیث میں راوی مجہول ہے، ضعیف ہے۔ پیشاب کے دوران کوشش کرنی چاہیے کہ اس کی چھینٹیں نہ پڑیں، ان سے احتیاط کی جائے۔ نرم جگہ تلاش کرنے سے بچاؤ ممکن ہے۔ اگر یہ روایت ضعیف ہے۔ علامہ عظیم آبادی فرماتے ہیں: «لَكِنْ لَا يَضُرُّ فَإِنَّ أَحَادِيثَ الْأَمْرِ بِالتَّنَزُّهِ عَنِ الْبَوْلِ تُفِيدُ ذَلِكَ» (عون المعبود: ۵/۱) ’’لیکن یہ ضعف نقصان رساں نہیں کیونکہ پیشاب سے پرہیز کے بارے میں وارد ہونے والی احادیث اس احتیاط کا فائدہ دیتی ہیں۔‘‘"}],[438,"مغیرہ رضی اللہ عنہ: نبی کریم صلی اللہ علیہ وسلم جب حاجت رفع کرنے کے لیے جاتے تو دور چلے جاتے تھے۔ (ترمذی)","",{"k":"ابوداود (1)۔ ترمذی (20)۔ نسائی (17)۔ ابن ماجہ (331)۔ دارمی (660)۔ حسن صحیح ہے۔ البانی: 1۔","m":"الْمَذْهَبَ یہ مصدر میمی، جانا، مراد قضائے حاجت کے لیے جانا۔ أَبْعَدَ افعال سے ماضی واحد مذکر غائب، اتنے زیادہ چلتے کہ آبادی سے دور ویرانے میں چلے جاتے۔"}],[439,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب حاجت رفع کرنے جاتے تو دور جاتے یہاں تک کہ آپ صلی اللہ علیہ وسلم کو کوئی نہ دیکھ رہا ہوتا تھا۔","",{"k":"ابوداؤد (2)۔ ابن ماجہ (335)۔ دارمی (17)۔ صحیح ہے۔ البانی: 2۔","m":"الْبَرَازَ باء کے نیچے کسرہ بھی آتا ہے، مفاعلہ سے مصدر ہے، وہ کھلی فضا جس میں درخت نہ ہوں، مراد قضائے حاجت ہے۔ انْطَلَقَ انفعال سے ماضی واحد مذکر غائب چلے گئے۔ لَا يَرَاهُ مضارع منفی واحد مذکر غائب، آپ صلی اللہ علیہ وسلم کو کوئی نہ دیکھتا تھا۔","e":"ان احادیث میں قضائے حاجت کے آداب بیان ہوئے ہیں کہ جس جگہ لوگ موجود ہوں اور تو قضائے حاجت پیش آ جائے تو لوگوں کی نظروں سے دور جانا چاہیے، اصل مقصد ہے کہ قضائے حاجت کے وقت پردہ ہو، خواہ وہ دور جا کر ہو، عمارتوں کا ہو، لیٹرین کا ہو، پردہ لگا کر ہو، گہرا گھڑا ہو، اس میں بیٹھے ہوں جہاں نظر نہ آئیں، یعنی شرمگاہ کے لیے جس صورت بھی پردہ ہو قضائے حاجت کے لیے وہ ہونا چاہیے۔"}],[440,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم دو لعنت کرنے والی چیزوں سے بچو۔ کہا گیا دو لعنت کرنے والی اشیائی کون سی ہیں؟ فرمایا: وہ جو حاجت رفع کرے لوگوں کے راستے میں یا ان کے سائے میں۔","",{"k":"مسلم (269)۔ کتاب الطہارۃ، ابو داود (25)۔ احمد (8636)۔","m":"اتَّقُوا افتعال سے امر جمع مذکر حاضر، بچو۔ اللَّعَّانَيْنِ یہ مفعول بہ ہے، تثنیہ ہے، دو لعنت کرنے والے یعنی وہ دو چیزیں جن کی وجہ سے لوگ لعنت کرتے ہیں۔ يَتَخَلَّى تفعل سے مضارع معلوم واحد مذکر غائب، قضائے حاجت کرتا ہے۔"}],[441,"سیدنا معاذ بن جبل رضی اللہ عنہ سے ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لعنت کے تین امور سے بچو! پانی کے گھاٹ پر، راستے میں اور سائے میں حاجت رفع کرنے سے۔","",{"k":"ابوداؤد (26)۔ ابن ماجہ (328)۔ حسن ہے۔ البانی: 21۔","m":"الْمَلَاعِنَ اس کا واحد مَلْعَنٌ ہے، یہ مصدر میمی بھی ہو سکتا ہے یعنی لعنت کا باعث بننے والی چیزوں سے بچو۔ یا یہ ظرف مکان ہے۔ تو مطلب ہے کہ لعنت کا سبب بننے والی جگہوں سے بچو۔ الْمَوَارِدَ اس کا واحد الْمَوْرِدُ ہے، پانی کی گھاٹ، چشمہ یا نہر وغیرہ۔ قَارِعَۃ یہ اسم فاعل ہے، کھٹکنے والا، یعنی وہ رستہ جہاں لوگوں کی آمد ورفت رہتی ہے۔"}],[442,"سیدنا حذیفہ بن اسید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے مسلمانوں کے راستے میں اذیت پھیلائی اس پر ان کی لعنت پڑے گی۔ (الکبیر)","",{"k":"طبرانی کبیر، اسنادہ حسن، ہیثمی: 1001۔","m":"آذَى افعال سے ماضی واحد مذکر غائب ہے، اذیت دی۔ طُرُقِهِمْ اس کا واحد طَرِيقٌ ہے، رستے۔ وَجَبَتْ واحد مونث غائب لازمی ہے۔","e":"۱۔ سیدنا حذیفہ بن اسید غفاری رضی اللہ عنہ، ابوریحہ ان کی کنیت ہے، صحابی ہیں۔ درخت کے نیچے بیعت کرنے والے صحابہ کرام رضی اللہ عنہم میں سے ہیں۔ ۴۲ ہجری میں وفات پائی۔ (تقریب) ۲۔ طبرانی والی حدیث میں لوگوں کی راہ گزر اور چالو راستے میں کسی بھی اذیت رسانی کو لازمی لعنت کا باعث قرار دیا گیا ہے۔ یہ اذیت رستہ تنگ کرنے، پریشان کرنے اور غلاظت پھیلانے سمیت ہر چیز کو شامل ہے۔ ۳۔ ان احادیث مبارکہ میں اس شخص پر نبی اکرم صلی اللہ علیہ وسلم نے سخت برہمی کا اظہار فرمایا ہے، لعنتی قرار دیا ہے کہ وہ بدنصیب اللہ کی رحمت سے محروم رہے گا، اور گالیاں کھا جائے گا جو یہ بیہودہ حرکت کرے گا، کہ لوگ جس راستے سے گزرتے ہیں جو کہ شارع عام ہے، اس پر پاخانہ یا پیشاب کرتا ہے، یا جہاں وہ پانی پیتے ہیں اس کے قریب غلاظت نکال جاتا ہے، یا درخت ہو جس کے سائے میں لوگ دوپہر کے وقت آرام کرتے تھے، یہ قریب گندگی کر جاتا ہے اس سے لوگ سفر کی سہولتوں سے محروم ہوتے ہیں، اس لیے اسے بہت سخت ناپسندیدہ اور مبغوض عمل قرار دیا گیا ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ فرماتے ہیں: البتہ اگر یہ مقامات استعمال میں نہیں اور لوگ سائے کے نیچے آرام نہیں کرتے جیسا کہ جنگل میں درخت ہوتے ہیں تو پھر مجبوراً قضائے حاجت ہو جائے تو گنجائش ہے، جیسا کہ حدیث میں آتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم جنگل میں ایک کھجور کے درخت کے جھنڈ کے نیچے قضائے حاجت بیٹھے تھے۔ (مسند احمد) میں ہے: أَوْ ظِلٍّ يُسْتَظَلُّ بِهِ ’’وہ سایہ جسے استعمال کیا جاتا ہو۔‘‘ ظاہر ہے جو استعمال نہ ہو اس کے نیچے حاجت میں کوئی حرج نہیں۔ (مرعاۃ: ۱/۴۱۵)\nثابت ہوا کہ لوگوں کے عام راستہ، ان کے سائے کی جگہ اور پانی کی گھاٹ کے قریب قضائے حاجت کرنا یا پیشاب کرنا حرام ہے کیونکہ اس سے بد بو پیدا ہوتی ہے، اور مسلمانوں کو اذیت ہوتی ہے۔"}],[443,"سیدنا عبد اللہ بن سرجس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سوراخ میں پیشاب کرنے سے منع فرمایا ہے۔ لوگوں نے قتادہ رضی اللہ عنہ سے سوال کیا: سوراخ (بل) میں پیشاب کرنا کیوں مکروہ ہے تو انہوں نے کہا: کہتے ہیں وہ جنوں کے مسکن اور ٹھکانے ہیں۔","",{"k":"ابوداود (29)۔ احمد (20251)۔ ضعیف ہے۔ البانی: 8۔ بتایا گیا ہے کہ قتادہ نے عبداللہ سے سماع حدیث نہیں کیا جبکہ علی بن مدینی اور ابو زرعہ نے سماع ثابت کیا ہے، اور ابو حاتم بھی کہتے ہیں کہ قتادہ حضرت انس اور عبداللہ بن سرجس سے ملے ہیں، ابن خزیمہ اور ابن سکن نے اسے صحیح قرار دیا ہے، حاکم اور بیہقی نے اس حدیث کو بخاری اور مسلم کی شرط پر قرار دیا ہے۔ (مرعاۃ: 1/425) ظاہر ہوتا ہے کہ صحیح والوں کی رائے درست ہے۔","m":"أَنْ يُبَالَ مضارع مجہول واحد مذکر غائب، ان نے نصب دیا ہے، یہ کہ پیشاب کیا جائے۔ الْجُحْرِ سوراخ جس میں کیڑے مکوڑے رہتے ہیں۔ مَا موصولہ ہے، مبتداء ہے، اس کی خبر مقدار ہے جو کہ لِمَاذَا ہے، کیوں مکروہ ہے۔ يُكْرَهُ مضارع مجہول واحد مذکر غائب، ناپسند کیا گیا ہے۔ إِنَّهَا یہ سوراخ۔ اصل جُحْرَۃٌ ہے، اس کے پیش نظر ضمیر مونث ہے، مَسَاكِنُ اس کا واحد مَسْكَنٌ ہے، سکون کی جگہ رہائش گاہیں۔","e":"۱۔ عبد اللہ بن سرجس رضی اللہ عنہ، مجمعہ اور علمیت کی وجہ سے غیر منصرف ہے۔ یہ مزینہ قبیلہ کے تھے، بنو مخزوم کے حلیف تھے، صحابی ہیں۔ بصرہ میں رہائش پذیر تھے۔ (تقریب) ۲۔ بل میں پیشاب کرنے کی ممانعت اس حدیث میں وارد ہوئی ہے، اس کی ایک وجہ تو یہی ہے جو یہاں بیان ہوئی ہے کہ جنوں کی رہائش گاہیں ہوتی ہیں، سرکش جنوں سے اس طرح نقصان پہنچ سکتا ہے۔ علاوہ ازیں یہ وجہ بھی ہے کہ یہ کیڑے مکوڑوں، بچھوؤں اور سانپوں اور زہریلے حشرات الارض کی پناہ گاہیں بھی ہیں، اس سے تکلیف ہوسکتی ہے، اس لیے بل میں پیشاب کرنے کی ممانعت ہے، واہ ہماری شریعت کس قدر باریک بین اور خیر خواہ ہے۔"}],[444,"سیدنا عبد اللہ بن مغفل رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: تم میں سے کوئی آدمی اپنے غسل خانے میں پیشاب نہ کرے عام طور اس سے وسوسے پیدا ہوتے ہیں۔ (ترمذی ونسائی)","",{"k":"نسائی (36)۔ عامۃ الوسواس کے الفاظ نسائی میں نہیں، صحیح ہے۔ البانی: 35۔ بخاری (4842)۔ ترمذی (21)۔ ابوداؤد (28)۔ ابن ماجہ (304)۔","m":"لَا يَبُولَنَّ نہی واحد مذکر غائب، بانون تاکید ثقیلہ، ہرگز نہ پیشاب کرے۔ مُسْتَحَمِّہ وہ جگہ جہاں غسل کیا جائے۔ عَامَّةَ اکثر۔ الْوَسْوَاسِ یہ واؤ کے کسرہ کے ساتھ بھی ہے، اس صورت میں مصدر ہے، اور فتحہ کے ساتھ بھی آتا ہے اس صورت میں اسم ہے، وسوسہ ہوتا ہے۔ مِنْهُ یہ پیشاب کرنے سے۔"}],[445,"اور ابوداؤد رحمہ اللہ نے یہ لفظ زائد کیا ہے۔ پھر اس میں غسل کرے اور امام احمد بن حنبل رحمہ اللہ نے کہا پھر اس میں وضو کرے۔","",{"k":"ابوداؤد (27)۔ صحیح، البانی: 22۔ بقیہ نمبر 444 والی تخریج۔"}],[446,"امام ابن ماجہ قزوینی رحمہ اللہ نے اس پر مزید اضافہ کر کے روایت کیا ہے کہ میں نے محمد بن یزید سے فرماتے ہوئے سنا کہ میں نے علی بن محمد طنافسی رحمہ اللہ سے سنا ہے کہ یہ حکم کچھے غسل خانوں کا ہے مگر اب تو چونا اور سیمنٹ اور قلعی سے غسل خانے بنائے جاتے ہیں پس اگر پیشاب کر کے اس پر پانی بہا دیا جائے تو پھر کوئی حرج نہیں ہے۔","",{"k":"ابن ماجہ (304)۔ بقیہ نمبر 444 والی تخریج۔","m":"الْحَفِيرَةِ گڑھا۔ فَمُغْتَسَلَاتُهُمْ ان کے غسل خانے۔ الْجَصُّ چونا، الصَّارُوجُ قلعی۔ وَالْقِيرُ تارکول۔ فَأَرْسَلَ افعال سے ماضی واحد مذکر غائب، اس پر چھوڑ دے، یا بہا دے۔","e":"ان احادیث کا مفاد یہ ہے کہ غسل خانے میں پیشاب نہ کیا جائے، آج کل جو پیچ ہاتھ ہوتے ہیں وہ اس سے مستثنیٰ ہیں کیونکہ ان میں فلش کا الگ انتظام ہوتا ہے، وہاں پیشاب جائز ہے، کیونکہ اس سے وسوسہ پیدا نہیں ہوتا اور غسل خانہ علیحدہ ہوتا ہے، وسوسہ اندازی یوں ہوتی ہے کہ حمام میں نہائیں اور وہیں پیشاب کیا ہو تو دل میں خیال آتا ہے کہ کہیں پیشاب کی چھینٹ نہ پڑ گئی ہو، اس سے بچنے کے لیے ضروری ہے کہ غسل خانہ میں پیشاب نہ کیا جائے۔ باقی رہا یہ اختلاف کہ کچی جگہ ہو وہاں گڑھے سے پڑے ہوں تو وہاں ممانعت ہے، جہاں، چونے کیچ ہو، پلستر ہو، یا چپس وغیرہ پڑی ہو تو وہاں پیشاب کر سکتا ہے اور اوپر پانی بہادے۔ یہ اختلاف قابل غور نہیں، حدیث کا تقاضا یہی ہے کہ زمین ٹھوس ہو یا غیر ٹھوس ہو۔ غسل خانے میں پیشاب سے احتراز کیا جائے، وجہ یہ ہے کہ ٹھوس یا غیر ٹھوس زمین پر پیشاب کرنے سے وسوسہ ضرور باقی رہتا ہے۔ لہذا غسل خانہ میں پیشاب کرنا منع ہے، حدیث کے دلائل اور عقل و فکر کا یہی مطالبہ ہے۔"}],[447,"سیدہ امیمہ بنت رقیقہ رضی اللہ عنہا روایت کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا لکڑی کا پیالہ تھا اس میں آپ صلی اللہ علیہ وسلم پیشاب کرتے تھے اور رات کو اس کو چار پائی کے نیچے رکھتے تھے۔","",{"k":"نسائی (32)۔ ابوداود (24)۔ حسن، صحیح ہے۔ البانی: 32۔","m":"قَدَحٌ اس کی جمع أَقْدَاحٌ ہے، پیالہ۔ عِيدَانِ عین پر فتحہ ہے، اس کا واحد عِيدَانَةٌ ہے، کھجور کی ٹہنی سے پیالہ تیار کیا ہوا۔ سَرِيرٌ اس کی جمع سُرُرٌ ہے، چار پائی، ضمیر رسول اکرم صلی اللہ علیہ وسلم کی جانب لوٹتی ہے، فِيهِ اس پیالہ میں۔"}],[448,"عبد اللہ بن یزید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تشتری میں پیشاب کر کے گھر میں نہ رکھا جائے۔ اس گھر میں فرشتے داخل نہیں ہوتے جس میں بول براز رکھا ہو۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط، سند حسن ہے۔ ہیثمی: 999۔","m":"لَا يُنْقَعُ مضارع منفی مجہول واحد مذکر غائب، دیر تک رہنے کی وجہ سے رنگ بدل جانا، یعنی دیر تک نہ رکھا جائے۔ طَسْتٌ تھال۔ فِيهِ جس گھر میں۔","e":"۱۔ امیمہ بنت رقیقہ رضی اللہ عنہا ان کے والد کا نام عبد اللہ بن بجاد تیمی ہے، صحابیہ ہیں، ان کی والدہ رقیقہ ام المومنین سیدہ خدیجہ رضی اللہ عنہا کی بہن تھیں۔ ایک امیمہ ثقفیہ تھیں، وہ اور ہیں وہ تابعیہ ہیں۔ (تقریب) ۲۔ عبد اللہ بن یزید انصاری رضی اللہ عنہ صغیر صحابی ہیں، حضرت ابن زبیر کے دور میں کوفہ کے گورنر تھے۔ (تقریب) ۳۔ پہلی حدیث سے تو ثابت ہوتا ہے کہ رات کسی برتن میں پیشاب کیا ہو تو اسے گھر میں رکھ سکتے ہیں۔ لیکن دوسری حدیث کا مفہوم اس کے برعکس ہے کہ برتن میں پیشاب رکھنے کی ممانعت ہے، دونوں کا ٹکراؤ اس طرح دور ہو گا کہ اجازت کی یہ صورت ہے کہ ضرورت کے تحت برتن میں پیشاب کیا ہو تو اسے کچھ دیر کے لیے جیسا کہ مذکور ہے رات بھر کے لیے گھر میں رکھ سکتے ہیں۔ اور ممانعت کی صورت یہ ہے کہ پیشاب برتن میں اتنی زیادہ دیر نہ پڑا رہے کہ اس کا رنگ بدل جائے۔ اور ممانعت کی ایک اور وجہ بھی ہو سکتی ہے کہ برتن میں گھر میں پیشاب کریں اور باہر پھینک دیں یہ جائز ہے، لیکن گھر میں بغیر برتن ایک جگہ پر کثرت سے پیشاب کرنا یہ گندگی کا باعث ہے، اس لیے اسی سے منع کیا گیا ہے۔ یاد رہے کہ لیٹرین وغیرہ مراد نہیں وہ تو گھروں میں بنائی ہی پیشاب وغیرہ کے لیے ہوتی ہے اور وہ صاف ہوتی رہتی ہیں، وہ اس ممانعت میں شامل نہیں۔"}],[449,"سیدنا ابوایوب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم بول براز کرنے جاؤ تو قبلہ کی طرف نہ منہ کیا کرو اور نہ پیٹھ مگر شرقاً غرباً پھر جاؤ۔‘‘ انہوں نے کہا کہ جب ہم شام گئے تو ہم نے بیت الخلاء دیکھے جو قبلہ کے رخ پر بنائے گئے تھے پس ہم دوسری جانب پھر کر پیشاب وغیرہ کرتے اور اللہ سے مغفرت طلب کرتے۔","",{"k":"بخاری (394)۔ مسلم (364)۔ نسائی (22)۔ ابوداود (9)۔ ابن ماجہ (318)۔ احمد (23065)۔","m":"أَتَيْتُمْ ماضی جمع مذکر حاضر، جب تم آؤ۔ فَلَا تَسْتَقْبِلُوا استفعال سے نہی جمع مذکر حاضر، منہ نہ کرو۔ وَلَا تَسْتَدْبِرُوهَا استفعال سے نہی جمع مذکر حاضر، ادھر پیٹھ نہ کرو۔ شَرِّقُوا تفعیل سے جمع مذکر حاضر امر، مشرق کی جانب اختیار کرو۔ غَرِّبُوا تفعیل سے امر حاضر جمع مذکر، مغرب کی جانب اختیار کرو۔ مَرَاحِيضَ اس کا واحد مِرْحَاضٌ ہے، حاجت گاہ۔ بُنِيَتْ ماضی مجہول واحد مونث غائب، بنائی گئیں۔ فَتَنْحَرِفُ انفعال سے مضارع معلوم جمع متکلم، ہم فارغ ہو کر واپس آتے۔"}],[450,"سیدنا ابوایوب رضی اللہ عنہ نے یہ بات مصر میں کہی ہے کہ اللہ کی قسم! میں نہیں جانتا کہ میں پوشیدہ خانوں کو کیسے استعمال کروں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص حاجت رفع کرنے جائے تو قبلہ کی طرف نہ منہ کرے اور نہ پیٹھ۔‘‘","",{"k":"مالک: 453۔ بخاری (144)۔ مسلم (264)۔ نسائی (22)۔ ابوداود (9)۔ ابن ماجہ (318)۔ احمد (23065)۔ دارمی (665)۔","m":"مَا أَدْرِي، ضَرَبَ سے مضارع معلوم واحد متکلم، میں نہیں جانتا۔ أَصْنَعُ مضارع واحد متکلم، میں کروں۔ اَلْكَرَابِيسُ اس کا واحد الْكِرْبَاسُ ہے، لیٹرین۔"}],[451,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’میں تمہارے لیے بمنزل باپ کے ہوں تمہیں تعلیم دیتا ہوں۔ جب تم میں سے کوئی شخص حاجت رفع کرنے جائے۔‘‘ (طویل حدیث تا آخر)","",{"k":"ابوداود (8)۔ حسن ہے۔ البانی: 6۔ بخاری (3860)۔ نسائی (40)۔ ابن ماجہ (313)۔ احمد (7321)۔ دارمی (674)۔","m":"أُعَلِّمُكُمْ تفعیل سے مضارع معلوم واحد متکلم، ضمیر مفعول بہ، میں تمہیں سکھاتا ہوں۔","e":"انتباہ: اس کی تکمیل یہ ہے کہ جب تم میں سے کوئی قضائے حاجت کو آئے تو نہ تو قبلہ کی جانب منہ کرے اور نہ ہی پشت کرے اور نہ ہی دائیں ہاتھ سے استنجاء کرے اور استنجا تین پتھروں سے کرے اور لید یا گوبر اور بوسیدہ ہڈی کے ساتھ استنجا نہ کرو۔"}],[452,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مرفوع روایت ہے: ’’جو شخص بوقت بول و براز نہ قبلہ کی طرف منہ کرے اور نہ پیٹھ تو اس کے لیے ایک نیکی لکھی جاتی ہے اور اس کا ایک گناہ مٹا دیا جاتا ہے۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط، رجالہ رجال الصحیح، مگر شیخ طبرانی اور اس کا شیخ دونوں ثقہ ہیں۔ ہیثمی: 1014۔","m":"مُحِيَ ماضی مجہول واحد مذکر غائب، مٹا دی جاتی ہے۔"}],[453,"مروان الاصفر نے کہا میں نے ابن عمر رضی اللہ عنہ کو دیکھا کہ انہوں نے اپنا اونٹ قبلہ کی طرف بٹھایا اور پھر اس کی طرف پیشاب کرنے لگے۔ میں نے کہا اس سے منع نہیں کیا گیا؟ انہوں نے کہا ممانعت تو صحرا کے لیے کی گئی ہے، اور اگر تیرے اور قبلے کے درمیان کسی چیز کا پردہ ہو تو پھر کوئی حرج نہیں ہے۔ (ابوداؤد)","",{"k":"ابوداود (11)۔ حسن ہے۔ البانی: 8۔","m":"أَنَاخَ افعال سے ماضی واحد مذکر غائب، سواری کو بٹھایا۔ رَاحِلَتَهُ سواری۔ مُسْتَقْبِلَ استفعال سے اسم فاعل، حال ہونے کی وجہ سے منصوب ہے، اس حال میں کہ منہ۔ إِلَيْهَا اس سواری کی طرف۔ يَسْتُرُكَ، نَصَرَ سے مضارع معلوم واحد مذکر غائب ضمیر مفعول بہ ہے، تجھے پردہ کرے۔"}],[454,"سیدنا ابن عمر رضی اللہ عنہ نے کہا: میں اپنے کام کے لیے ام المومنین حفصہ رضی اللہ عنہا کے مکان پر چڑھا تو رسول اللہ صلی اللہ علیہ وسلم کو شام کی طرف منہ کر کے اور قبلہ کی طرف پیٹھ پھیر کر حاجت کرتے دیکھا۔","",{"k":"بخاری (148)۔ مسلم (266)۔ نسائی (23)۔ ابوداود (12)۔ ابن ماجہ (322)۔ احمد (5682)۔ مالک: 455۔ دارمی (667)۔","m":"ارْتَقَيْتُ افتعال سے ماضی واحد متکلم، میں چڑھا۔"}],[455,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے وہ کہتی ہیں رسول اللہ صلی اللہ علیہ وسلم کے سامنے بیان کیا گیا کہ کچھ لوگ قبلہ کی طرف منہ کرنا مکروہ سمجھتے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میرا گمان ہے وہ ایسا ہی کرتے ہیں۔ تم دونوں شرمگاہوں کو قبلہ کی طرف کر سکتے ہو۔‘‘","",{"k":"ابن ماجہ (324)۔ احمد (25371)۔ ضعیف ہے۔ البانی: 68۔","e":"ان تمام احادیث کی وضاحت یہ ہے کہ قضائے حاجت کے لیے قبلہ کی جانب نہ تو منہ کیا جائے اور نہ ہی پیٹھ کی جائے۔ لیکن اگر اس مقام پر ہوں جہاں مشرق کی جانب کریں یا مغرب کی جانب منہ کریں نہ تو قبلہ کی جانب منہ ہو اور نہ ہی پیٹھ ہو تو پھر مشرق اور مغرب کی جانب منہ کر لیں، اگر پیٹھ یا منہ قبلہ کی جانب آتا ہو تو پھر شمال یا جنوب کی جانب کیا جائے۔ ایک تعارض: بعض روایات میں صحراء اور عمارتوں کا فرق آیا ہے کہ صحراء میں قبلہ رخ نہ ہوا جائے، عمارتوں میں جائز ہے۔ ایک قول یہ ہے کہ صحراء میں بھی اور غیر صحراء میں بھی قبلہ رخ ہونا جائز ہے۔ ان میں کوئی فرق نہیں۔ یہ قول غلط ہے۔ (اس کا حل) ان میں سے صحیح ترین بات یہی ہے کہ قضائے حاجت کے وقت مطلق طور پر قبلہ کی جانب منہ کرنا، یا پیٹھ کرنا منع ہے، صحراء ہو یا عمارتیں ہوں۔ ایک رسول اکرم صلی اللہ علیہ وسلم کا عمل ہوتا ہے، ایک آپ کا قول ہے، ان میں ٹکراؤ ہو تو ترجیح قول کو ہوتی ہے۔ علامہ عبید اللہ رحمانی فرماتے ہیں: اَلْاِحْتِرَازُ عَنِ الْاِسْتِقْبَالِ وَالْاِسْتِدْبَارِ فِي الْبُيُوتِ أَحْوَطُ وُجُوبًا. (مرعاة: ۴۱۱/۱) ’’گھروں میں بھی قضائے حاجت کے لیے قبلہ کی جانب منہ کرنا، یا پیٹھ کرنا احتیاطاً واجب ہے کہ منہ یا پیٹھ قبلہ رخ نہ کی جائے۔‘‘ ۲۔ بعض روایات میں آیا ہے کہ سیدنا ابن عمر رضی اللہ عنہ کہتے ہیں، میں حفصہ رضی اللہ عنہا کے گھر میں آیا اور چھت پر چڑھا، بعض میں نبی صلی اللہ علیہ وسلم کے گھر کا ذکر ہے، بعض میں آتا ہے، میں اپنے گھر میں آیا اور چھت پر چڑھا۔ تو ان میں مطابقت یہ ہے کہ اصل ملکیت نبی صلی اللہ علیہ وسلم کی تھی، بیوی کی حیثیت سے گھر کی نسبت سیدہ حفصہ رضی اللہ عنہا کی جانب کی اور بہن کے گھر کو سیدنا ابن عمر رضی اللہ عنہ اپنا گھر کہہ رہے ہیں، اصل میں یہ گھر نبی صلی اللہ علیہ وسلم کا تھا جس پر آپ کو قضائے حاجت کرتے دیکھا۔ ۳۔ ان سے یہ بھی ثابت ہوتا ہے کہ دائیں ہاتھ سے استنجاء منع ہے، اور لید اور گوبر اور ہڈی سے استنجاء منع ہے، اس سے ایک تو صفائی حاصل نہیں ہوتی۔ علاوہ ازیں ہڈی جنوں کی خوراک ہے اور گوبر ان کے جانوروں کی خوراک ہے۔ اور یہ بھی ثابت ہوا کہ تین پتھروں سے کم سے استنجا نہ کیا جائے۔ جن احادیث میں تین سے کم پتھروں سے استنجا کرنے کا آتا ہے، وہ ضعیف ہیں۔ (مرعاۃ: ۱/۴۱۳)"}],[456,"ابووائل سے روایت ہے کہ سیدنا ابو موسی رضی اللہ عنہ پیشاب کے بارے میں تشدد کرتے تھے اور وہ ایک بوتل میں پیشاب کرتے تھے اور کہتے تھے بنو اسرائیل کی کھال کو اگر پیشاب لگ جاتا تو اس کو قینچی سے کاٹتے تھے۔ حذیفہ رضی اللہ عنہ نے کہا: مجھے تو یہ پسند ہے کہ یہ تمہارا رفیق اس قدر تشدد نہ کرتا تو بہتر ہوتا۔ میں نے اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلتے دیکھا ہے کہ ہم چلتے جا رہے تھے پھر آپ صلی اللہ علیہ وسلم ایک قوم کے کوڑے کرکٹ کی جگہ پر گئے جو دیوار کی اوٹ میں تھا، پھر آپ صلی اللہ علیہ وسلم کھڑے ہوئے جیسے تم کھڑے ہوتے ہو اور میں آپ سے فاصلے پر جا کھڑا ہوا تو آپ نے میری طرف اشارہ کیا۔ میں قریب آ کر آپ صلی اللہ علیہ وسلم کی ایڑیوں کے پیچھے کھڑا ہوا یہاں تک کہ آپ صلی اللہ علیہ وسلم فارغ ہو گئے۔","",{"k":"مسلم (273)۔ کتاب الطہارۃ۔ بخاری (2471)۔ ترمذی (94)۔ نسائی (28)۔ ابوداود (23)۔ ابن ماجہ (543)۔ احمد (22906)۔ دارمی (668)۔","m":"يُشَدِّدُ تفعیل سے مضارع معلوم واحد مذکر غائب سختی کرتے، اسے بہت سخت حکم قرار دیتے۔\nقَارُورَةٍ بوتل۔ قَرَضَهُ ماضی واحد مذکر غائب، ضمیر کپڑے کی جانب لوٹتی ہے، مفعول بہ ہے۔ اسے کاٹتے، الْمَقَارِيضُ اس کا واحد مِقْرَاضٌ ہے، قینچی۔ صَاحِبَكُمْ مراد، حضرت ابو موسیٰ ہیں۔ فَتَمَاشَى تفاعل سے مضارع معلوم جمع متکلم، ہم چل رہے تھے۔ سُبَاطَة کوڑا کرکٹ کی جگہ۔ فَانْتَبَذْتُ مِنْهُ افتعال سے ماضی واحد متکلم میں دور چلا گیا آپ صلی اللہ علیہ وسلم سے۔ فَأَشَارَ افعال سے ماضی واحد مذکر غائب اشارہ کیا آپ نے۔ إِلَيَّ ضمیر مجرور ہے، میری طرف۔ عَقِبِهِ ایڑی کے قریب۔ فَرَغَ ماضی واحد مذکر غائب، آپ فارغ ہوئے۔"}],[457,"سیدنا عمر رضی اللہ عنہ نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے کھڑا ہو کر پیشاب کرتے دیکھا تو فرمایا: اے عمر! کھڑے ہو کے پیشاب نہ کیا کرو، چنانچہ میں نے اس کے بعد کھڑے ہو کر پیشاب نہیں کیا۔","",{"k":"نسائی (29)۔ ابن ماجہ (307)۔ ضعیف ہے۔ البانی: 2۔ ترمذی (12)۔"}],[458,"اور ترمذی کی ایک روایت ہے کہ عمر رضی اللہ عنہ نے کہا: میں جب سے مسلمان ہوا ہوں میں نے کھڑے ہو کر پیشاب نہیں کیا۔","",{"k":"ترمذی (12)۔"}],[459,"اور ترمذی کی روایت میں ابن مسعود رضی اللہ عنہ سے منقول ہے: گناہ کی بات ہے کہ تو کھڑے ہو کر پیشاب کرے۔","",{"k":"ترمذی (12)۔","m":"الْجَفَاءُ ظلم ہے۔"}],[460,"سیدہ عائشہ رضی اللہ عنہا نے کہا: جو شخص تم سے بیان کرے کہ نبی کریم صلی اللہ علیہ وسلم کھڑے ہو کر پیشاب کرتے تھے تو تم اس کی تصدیق نہ کرو۔ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر پیشاب کرتے تھے۔","",{"k":"ترمذی (12)۔ نسائی (29)۔ ابن ماجہ (7)۔ 3۔ صحیح ہے۔ البانی: 11۔"}],[461,"ابن سیرین رحمہ اللہ نے کہا: سعد بن عبادہ رضی اللہ عنہ ٹیک لگا کر کھڑے ہو کر پیشاب کر رہے تھے۔ جنات نے ان کو قتل کیا تو جنات نے کہا ہم نے خزرج کے سردار سعد بن عبادہ کو قتل کر دیا ہے۔ ہم نے تیر مارا اور وہ اس کے دل پر لگنے سے خطا نہ گیا۔","",{"k":"طبرانی کبیر: یہ ضعیف ہے، ابن سیرین نے سعد بن عبادہ سے ملاقات نہیں کی ان سے نہیں ملے، انقطاع ہے۔ ہیثمی: 17۔ 10۔","e":"ان تمام احادیث کا خلاصہ یہ ہے کہ جن احادیث میں پیشاب کھڑا ہو کر کرنے کی ممانعت آئی ہے، وہ یا تو موقوف ہیں، یا ضعیف ہیں۔ صحیح ترین بات یہ ہے کہ رسول اکرم صلی اللہ علیہ وسلم سے بسند صحیح غیر منسوخ طور پر ثابت ہے کہ آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب کیا ہے۔ ۲۔ یہ جو آتا ہے کہ سیدنا عمر رضی اللہ عنہ نے کہا کہ مجھے نبی صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب کرنے سے منع کیا تھا۔ یہ ان کا قول ہے نبی اکرم صلی اللہ علیہ وسلم تک سند ثابت نہیں، بلکہ سیدنا عمر رضی اللہ عنہ سے کھڑے ہو کر پیشاب کرنا ثابت ہے۔ (مرعاۃ: ۱/ ۴۳۱) ۳۔ باقی اب ٹکراؤ ہے کہ صحیح حدیث سے کھڑے ہو کر پیشاب کرنا ثابت ہوتا ہے، اور صحیح حدیث سے ہی ممانعت ثابت ہے۔ تو اس کا حل یہ ہے کہ ایک تو مطابقت یوں ہوگی کہ جو ممانعت کا ثبوت ہے، وہ سیدہ عائشہ رضی اللہ عنہا سے ہے، یہ درست ہے کیونکہ گھر میں آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب نہیں کیا، گھر سے باہر کیا ہے۔ دوسری بات یہ ہے کہ بیٹھ کر ہی پیشاب کیا جائے، اسے ہی عادت بنایا جائے۔ مگر کھڑے ہو کر کا جواز ہے اور اسے اجازت تصور کیا جائے عادت نہ بنایا جائے۔ ۴۔ اور جو یہ کہا جاتا ہے کہ آپ صلی اللہ علیہ وسلم نے اس لیے کھڑے ہو کر پیشاب کیا تھا کہ آپ کے پاؤں کی موچ وغیرہ یا گھٹنے میں تکلیف تھی، یہ احتمالات سب کمزور ہیں، بے ثبوت ہیں، کھڑے ہو کر پیشاب آپ نے جواز کے لیے کیا تھا۔"}],[462,"سیدنا عبد اللہ بن جعفر رضی اللہ عنہ سے مروی ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے پیچھے سواری پر بٹھایا اور پھر مجھ سے مخفی بات کی جو میں کبھی کسی انسان کو نہیں بتاؤں گا اور عبد اللہ وہی کچھ پسند کرتے تھے جس چیز سے رسول اللہ صلی اللہ علیہ وسلم نے پردے کا کام لیا تھا خواہ کوئی ٹیلہ ہوتا یا کھجور کا باغ ہوتا۔","",{"k":"مسلم (342)۔ ابوداود (2549)۔ ابن ماجہ (340)۔ احمد (1747)۔ دارمی (755)۔","m":"أَرْدَفَنِي افعال سے ماضی واحد مذکر غائب، نون وقایہ یاء مفعول بہ ہے۔ مجھے پیچھے سوار کیا۔ فَأَسَرَّ افعال سے ماضی واحد مذکر غائب، پوشیدہ رکھا۔ إِلَيَّ ضمیر مجرور واحد متکلم، میری طرف۔ بِهِ وہ بات نہ بتاؤں گا۔\nأَحَبَّ افعال سے ماضی واحد مذکر غائب پسند کرتے تھے۔ مَا اسم موصول جو اسْتَتَرَ استفعال سے ماضی واحد مذکر غائب، پردہ کیا۔ هَدَفٌ بلند زمین یا حَائِشٌ کھجور کی دیوار۔"}],[463,"سیدنا عبد الرحمن بن حسنہ رضی اللہ عنہ سے روایت ہے کہ میں اور عمرو بن عاص نبی صلی اللہ علیہ وسلم کی طرف آئے رسول اللہ صلی اللہ علیہ وسلم تشریف لائے آپ صلی اللہ علیہ وسلم کے پاس موٹی سی چیز تھی۔ آپ صلی اللہ علیہ وسلم نے اس سے پردہ کر کے اس کی طرف پیشاب کیا تو ہم نے کہا: ان کو دیکھو تو اس طرح پیشاب کرتے ہیں جیسے عورت پیشاب کرتی ہے۔ آپ صلی اللہ علیہ وسلم نے ہماری گفتگو سنی اور فرمایا: تمہیں معلوم نہیں کہ بنو اسرائیل کے رفیق کے ساتھ کیا معاملہ پیش آیا۔ بنو اسرائیل میں سے کسی کو اگر پیشاب لگ جاتا تو اس جگہ کو وہ کاٹ دیتے تھے پس ان کے رفیق نے ان کو منع کیا تو اس کو قبر میں عذاب دیا گیا۔","",{"k":"ابوداود (22)۔ نسائی (30)۔ صحیح البانی: 16۔","m":"دَرَقَةٌ ڈھال۔ فَنَهَاهُمْ پس۔ نَهَا ماضی واحد مذکر غائب، منع کیا اس نے۔ ضمیر مفعول بہ ہے، انہیں۔ فَعُذِّبَ تفعیل سے ماضی مجہول واحد مذکر غائب، عذاب دیا گیا۔"}],[464,"ایک اور روایت میں ہے: ’’ان کی کھال کو۔‘‘","",{"k":"ابوداود (22)۔ موقوف، صحیح۔ البانی: 17۔"}],[465,"دوسری روایت میں ہے: ’’ان کے جسم کو۔‘‘","",{"k":"ابوداود (22) منکر ہے۔","e":"اس میں جو آیا ہے کہ جہاں جسم پر پیشاب جائے اسے کاٹتے تھے، یہ ضعیف بات ہے اور غلط ہے، چمڑہ وغیرہ یا لباس کاٹنے والی بات درست ہے۔\n۲۔ ان احادیث سے یہ ثابت ہوا کہ قضائے حاجت کے وقت ایسا پردہ ہونا چاہیے جہاں سے آدمی کا وجود لوگوں کی نظروں سے اوجھل رہے، نظر نہ آئے، یہ بہت ہی پختہ حکم ہے۔ ۳۔ اس سے یہ بھی ثابت ہوتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے زجر و توبیخ کی ہے اور بنو اسرائیل نے جو اس حکم کی نافرمانی کی تھی اور اس کی وجہ سے جو وہ عذاب میں مبتلا ہوئے تھے۔ آپ صلی اللہ علیہ وسلم نے وہ تاریخ اس اعتراض کرنے والے کے سامنے رکھی تھی کہ انہوں نے اپنے دین کے ایک نیک حکم کی مخالفت کی تو عذاب میں مبتلا ہوئے اور تم بھی وہی طریقہ اپنانا چاہتے ہو، لہذا پیشاب کی نجاست سے مکمل طور پر احتراز کرو کہیں پہلی امتوں کی مانند گرفتار عذاب نہ ہو جانا۔ اور میں اس وجہ سے چھپ چھپ کر پیشاب کرتا ہوں اور تم مجھے عورتوں کی مانند پیشاب بیٹھنے کا طعنہ دیتے ہو، یہ کوئی معمولی بات نہیں ہے۔"}],[466,"سیدنا ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اکرم صلی اللہ علیہ وسلم سے فرماتے سنا ہے کہ دو مرد نہ نکلیں پاخانہ کرنے کے لیے اس حال میں کہ دونوں نے ستر ننگے کیے ہوں اور باتیں کر رہے ہوں کیونکہ اللہ ایسی باتوں سے ناراض ہوتا ہے۔","",{"k":"ابوداود (15)۔ احمد (10917)۔ ضعیف، البانی: 74۔"}],[467,"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب حاجت رفع کرنا چاہتے تو اپنا کپڑا اوپر نہ اٹھاتے یہاں تک کہ زمین کے قریب ہو جاتے۔","",{"k":"ابوداود (14)۔ ضعیف۔ اس میں جہالت ہے، حسین بن عبید اللہ بجلی ایک سند میں آتا ہے، کان یضع الحدیث، ہیثمی: 1/ 420۔ اخرجہ الترمذی (14)۔ دارمی (666) لیکن البانی رحمہ اللہ کہتے ہیں۔ صحیح: 11۔","m":"حَتَّى يَدْنُوَ، نصر سے مضارع معلوم واحد مذکر غائب، ان پوشیدہ کی وجہ سے منصوب ہے۔ یہاں تک کہ قریب ہو جائے۔","e":"اس میں قضائے حاجت کا ادب سکھایا گیا ہے کہ شرمگاہ سے کپڑا بوقت ضرورت اٹھانا ہے، تا کہ ستر کی حفاظت ہو اور کپڑا نجاست سے بھی محفوظ رہے۔\nصحراء ہو یا گھر ہو یا حاجت گاہ ہو سب کا یہی حکم ہے کیونکہ بلا ضرورت ستر اٹھانے کی ممانعت ہے، ہمہ وقت اس ادب کو ملحوظ رکھا جائے۔ اس سے یہ بھی ثابت ہوتا ہے کہ شریعت فضولیات سے کس قدر اجتناب کی تلقین کرتی ہے۔"}],[468,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جو سرمہ لگائے تو طاق بار لگائے جس نے ایسا کیا تو بہتر ہے اور جس نے ایسا نہ کیا تو کوئی حرج نہیں ہے جس نے خوشبو لگائی تو وہ طاق بار لگائے یہ بہتر ہے اور جس نے ایسا نہ کیا تو کوئی حرج نہیں ہے جس نے کچھ کھایا اور دانتوں میں سے کوئی چیز نکالی تو اس کو پھینک دے اور جو زبان کے ساتھ نکالی تو اس کو اندر اتار لے جس نے ایسا کیا تو بہتر ہے اور جس نے ایسا نہ کیا تو کوئی حرج نہیں (جو پیشاب وغیرہ) کرنے کے لیے جائے وہ چھپ کر بیٹھے اگر کوئی پردہ نہ ملے تو ریت کا ٹیلہ جمع کر کے اس کی طرف پیٹھ کر لے کیونکہ شیطان بنو آدم کی پشت سے کھیلتا ہے جس نے کیا اس نے اچھا کیا اور جس نے نہ کیا اس پر کوئی حرج نہیں ہے۔‘‘","",{"k":"ابوداود (35)۔ بخاری (162)۔ مسلم (237)۔ نسائی (88)۔ ابن ماجہ (409)۔ احمد (27282)۔ مالک: 34۔ دارمی (662)۔","m":"اِكْتَحَلَ افتعال سے ماضی واحد مذکر غائب، سرمہ ڈالا اس نے فَلْيُوتِرْ افعال سے امر غائب واحد مذکر، وتر کرے، طاق رکھے۔ اِسْتَجْمَرَ استفعال سے ماضی واحد مذکر غائب، استنجاء کرے۔ تَخَلَّلَ تفعل سے ماضی واحد مذکر غائب، دانتوں کے درمیان رہ جانے والی چیز۔ لَاكَ ماضی واحد مذکر غائب، منہ میں گھومنے والی چیز۔ فَلْيَبْتَلِعْ افتعال سے امر غائب واحد مذکر، نگل جانا چاہیے۔ كَثِيبًا ڈھیر۔ فَلْيَسْتَدْبِرْهُ استفعال سے امر غائب، پیچھے کر لے اسے۔ بِمَقَاعِدِ اس کا واحد مَقْعَدٌ بیٹھنے کی جگہ۔","e":"اس حدیث میں طاق تعداد میں سرمہ پہننے کا حکم ہے۔ تین سلاخیں ایک آنکھ میں اور تین ہی دوسری میں۔ لیکن یہ ضروری نہیں جو کرتا ہے وہ اچھا کرتا ہے، جو نہیں کرتا گناہ نہیں۔ شمائل ترمذی میں آتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک سرمہ دانی رکھی ہوئی تھی جس سے سرمہ لے کر آپ اپنی ایک آنکھ میں تین مرتبہ اور دوسری آنکھ میں بھی تین مرتبہ سرمہ ڈالتے تھے۔\n۲۔ اس میں طاقت پتھروں یا ڈھیلوں سے استنجاء کا حکم ہے، جیسا کہ پہلے گزر چکا ہے کہ کم از کم تین ڈھیلے ہوں، اس سے زیادہ جتنے بھی ہوں طاق ہوں۔ ۳۔ ہدایت یہ ہے کہ آدمی کھانا کھا رہا ہو تو دانتوں میں اس میں سے کچھ اگر پھنس جائے تو اسے دانت سے نکال کر باہر پھینک دیا جائے کیونکہ اس سے اس میں تغیر آجاتا ہے اور یہ گندہ ہو جاتا ہے۔ جو طبیعت اور صحت کے لیے ناگوار ہے۔ البتہ اگر زبان کے ساتھ خود بخود اسی وقت نکل کر منہ میں آجائے تو کوئی حرج نہیں۔ اس سے ناخوشگواری پیدا نہیں ہوتی۔ ۴۔ قضائے حاجت کا ادب سکھایا گیا ہے کہ پردہ کیا جائے خواہ مٹی یا ریت اکٹھی کر کے اس کا پردہ بنا لیا جائے، وگرنہ شیطان شرانگیزی کرتا ہے اگر پردہ کر لیا جائے تو پھر شیطان سے حفاظت رہتی ہے، یہ تمام امور بہتر ہیں ان پر عمل سے ثواب ہو گا انہیں چھوڑنے سے گناہ نہیں۔"}],[469,"سیدنا ابن عمر رضی اللہ عنہما سے نبی کریم صلی اللہ علیہ وسلم مقام مغمس تک مرفع حاجت کے لیے دور جاتے تھے۔ نافع رحمہ اللہ کہتے ہیں مکہ مکرمہ سے مقام مغمس دو میل کے فاصلے پر ہے۔‘‘ (الموصلی)","",{"k":"ابو يعلى طبرانی کبیر ورجالہ ثقات من اهل الصحيح۔","e":"اس سے ثابت ہوا کہ قضائے حاجت کے لیے دور جانا مسنون ہے، یہ تب ہے جب کھلی فضا ہو، اگر لوگوں کی موجودگی میں ہو حاجت گاہ بنی ہو، پردہ لٹکایا ہو یا گڑھا وغیرہ ہو تو پھر اتنی دور جانے کی ضرورت نہیں۔"}],[470,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم اسی طرح جگہ تلاش کرتے تھے بول براز کے لیے جیسے ٹھہرنے کے لیے جگہ دیکھتے تھے۔‘‘ (الاوسط)","",{"k":"طبرانی اوسط، اس میں یحییٰ بن عبید بن وحی عن ابیہ ہے، یہ مجہول ہے۔"}],[471,"بنو مدلج کے ایک آدمی سے روایت ہے، وہ اپنے باپ سے بیان کرتا ہے کہ سراقہ بن مالک بن جعشم رسول اکرم صلی اللہ علیہ وسلم کے پاس سے آئے اور وہ کہتے ہیں کہ کہا رسول اللہ صلی اللہ علیہ وسلم نے مجھے اس طرح اور اس طرح طریقہ تعلیم کیا ہے۔ پس ایک مرد نے مذاق میں کہا: تجھے یہ بھی تعلیم دی ہے کہ تو بول براز کیسے کرے؟ تو انہوں نے کہا: ہاں قسم اس ذات کی جس نے آپ صلی اللہ علیہ وسلم کو حق کے ساتھ نبی بنا کر مبعوث فرمایا ہے کہ آپ صلی اللہ علیہ وسلم نے ہمیں بتایا ہے کہ ہم بائیں پاؤں پر بوجھ ڈال کر دائیں پاؤں کو کھڑا کریں۔","",{"k":"طبرانی کبیر: 6605 رجل لم يسم."}],[472,"سیدنا ابوامامہ رضی اللہ عنہ نے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پیشاب سے بچو قبر میں سب سے پہلے حساب اسی کا لیا جاتا ہے۔‘‘ (الکبیر)","",{"k":"طبرانی کبیر: 7605، ورجالہ موثوقون ہیثمی: 1034۔","m":"يُحَاسَبُ مفاعلہ سے مضارع مجہول، حساب کیا جائے گا۔","e":"اس کی تائید وہ حدیث بھی کرتی ہے جس میں نبی صلی اللہ علیہ وسلم نے دو قبر والوں کے متعلق فرمایا تھا کہ ایک چغلی کھاتا تھا اور دوسرا پیشاب سے پرہیز نہ کرتا تھا، اس وجہ سے ان دونوں کو عذاب قبر ہو رہا ہے۔ (بخاری، کتاب الطہارة، جنائز وغیرہ مسلم، کتاب الطہارة)"}],[473,"سیدنا واثلہ بن اسقع رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی یہ نہ کہے کہ میں پانی بہاتا ہوں بلکہ یہ کہے کہ میں پیشاب کرتا ہوں۔‘‘ (الکبیر سند ضعیف ہے)","",{"k":"طبرانی کبیر، يضعف، وفيه عنبسہ بن عبدالرحمن عنبسہ وقد اجمعوا على صنعہ۔"}],[474,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب بیت الخلا جاتے تو اپنی انگوٹھی اتار دیتے تھے۔","",{"k":"ترمذی (1746)، نسائی (5213)، ابوداود (19)، ابن ماجہ (303)، ضعیف، البانی: 292۔"}],[475,"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم جب بیت الخلا میں داخل ہوتے تو اپنی انگوٹھی رکھ دیتے تھے۔","",{"k":"ابوداود (19) بقیہ اوپر والی منکر ہے۔ البانی: 50۔","e":"انتباہ: لیکن اس سے پہلے صحیح سند سے حضرت سلمان سے حدیث گزر چکی ہے جو اس کی تائید کرتی ہے۔ لیکن قضائے حاجت کے وقت بائیں پاؤں پر ٹیک لگانے کا ذکر اس میں نہیں۔"}],[476,"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بیت الخلا میں داخل ہوتے تو کہتے: اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ، ’’یا اللہ! میں تیری پناہ لیتا ہوں شیطان سے اور خبیث اشیاء سے۔‘‘","",{"k":"مسلم (375)، ترمذی (6)، نسائی (19)، ابوداود (4)، ابن ماجہ (296)، احمد (13587)، دارمی (669)۔"}],[477,"اور ایک روایت میں ہے: جب داخل ہونے کا ارادہ کرتے تھے۔","",{"k":"بخاری (142)۔"}],[478,"اور ایک روایت میں ہے کہ جب حاجت رفع کرنے کی جگہ جاتے۔","",{"k":"مسلم (375)، کتاب الحيض، بخاری (6322) بقیہ تخریج نمبر 476 والی ہے۔","m":"الْكَنِيفُ حاجت گاہ۔ اس کی جمع كُنُفٌ ہے۔"}],[479,"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی آدمی بیت الخلاء جائے تو وہ کہے: میں اللہ تعالیٰ کی پناہ میں آیا ہوں مذکر اور مونث شیاطین کے شر سے۔‘‘","",{"k":"ابوداود (6)، ابن ماجہ (296)، احمد (18844)، صحيح الباني: 4۔","m":"الْحُشُوشُ اس کا واحد حَشٌّ ہے، اصل میں گھنی کھجوروں کے درخت کو کہتے ہیں کیونکہ قضائے حاجت میں اس سے پردہ کا کام لیتے تھے، مراد حاجت گاہیں ہیں۔ مُحْتَضَرَةٌ افتعال سے اسم مفعول، مونث ہے، جن حاضر ہوتے ہیں۔","e":"قضائے حاجت کے لیے جو بھی جگہ ہو اس میں داخل ہونے کا ارادہ ہو تیاری ہو جائے تو یہ دعا پڑھی جائے۔ اس دعا میں اللہ تعالیٰ کے سامنے اظہار بندگی ہے۔ خُبث خبیث کی جمع ہے، موذی جنوں کو کہتے ہیں۔ الْخَبَائِثِ، خَبِيثَةٌ کی جمع ہے۔ اس سے مونث جن مراد ہیں۔ یہ مقام چونکہ ذکر الہی سے خالی ہوتا ہے، اتنی دیر آدمی ذکر الہی سے محروم رہتا ہے، اس لیے ان جنوں اور جنوں کی شرانگیزی سے اللہ تعالیٰ سے پناہ پہلے ہی طلب کر لی جاتی ہے تاکہ ان شریروں سے حفاظت رہے۔"}],[480,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب بیت الخلاء سے باہر آتے تو کہتے تھے: غفرانک، ’’اے اللہ! تیری مغفرت طلب کرتا ہوں۔‘‘","",{"k":"ترمذی (7)، ابوداود (30)، ابن ماجہ (300)، صحيح، الباني: 4۔","m":"غُفْرَانَكَ یہ مفعول بہ یا مفعول مطلق ہونے کی وجہ سے منصوب ہے، میں تجھ سے بخشش مانگتا ہوں، یا مجھے معاف کر دے۔"}],[481,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ جب نبی کریم صلی اللہ علیہ وسلم بیت الخلا سے باہر آتے تو کہتے: اَلْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي، ’’تمام تعریفیں اللہ کے لیے ہیں جس نے مجھ سے ایذا رساں چیز دور کر دی اور مجھے عافیت بخشی۔‘‘","",{"k":"ابن ماجہ (301)، ضعیف، البانی: 60۔"}],[482,"اور ایک روایت میں ہے اللہ کا شکر کہ خوراک کی اذایت مجھ سے دور کر دی اور اس کا نفع باقی رکھا۔ (رزین)","",{"k":"رزين.","e":"بیت الخلاء سے باہر آنے کا ادب بتایا گیا ہے کہ اللہ تعالیٰ سے طلب مغفرت کی جائے، کہا جائے اے میرے رب! مجھے ایسی مغفرت عنایت فرما دے جو تیری جناب کے لائق ہے میں اگرچہ اس کا مستحق نہ بھی ہوں پھر اپنے فضل سے مغفرت عطا کر دے۔ انسان چونکہ قضائے حاجت سے فراغت تک ذکر الہی سے محروم رہتا ہے، اس تقصیر پر اللہ تعالیٰ سے استغفار کیا گیا۔ دوسری وجہ یہ بھی ہے کہ یہ نجاست اگر پیٹ میں ہی رک جائے تو یہ ہلاکت کا باعث ہے، اس کا نکلنا ایک عظیم نعمت ہے اس کے بغیر صحت نہیں رہتی تو اس کا شکریہ ادا کرتے ہوئے مغفرت طلب کی جاتی ہے کہ پروردگار اگر اس نعمت کے شکریے میں کمی رہ جائے تو مجھے معاف کر دیتا۔\nانتباہ: علامہ نووی رحمہ اللہ فرماتے ہیں: قضائے حاجت سے فارغ ہو کر جو دعائیں آتی ہیں، ان میں صرف یہی سیدہ عائشہ رضی اللہ عنہا والی حدیث ثابت ہے۔ دوسری ثابت نہیں۔ (مرعاۃ: ۱/ ۴۲۹)"}],[483,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جنات کی آنکھوں کے درمیان اور تمہارے پردے کے مقام کے درمیان جب تم میں سے کوئی شخص بیت الخلاء جائے تو پردہ یہ ہے کہ وہ کہے ’’بسم اللہ‘‘ (ترمذی)","",{"k":"ترمذی (606)، ابن ماجہ (297)، صحيح الباني: 496۔","m":"سَتْرُ پردہ، یہ مصدر ہے۔ مَا بَيْنَ أَعْيُنِ الْجِنِّ ما صولہ ہے۔ عین کی اعین ہے۔ ستر مبتداء ہے، یہ سارا جملہ آگے خبر ہے معنی ہوا جو جنوں کی آنکھوں کے درمیان پردہ ہے۔ عَوْرَاتِ اس کا واحد عَوْرَةٌ ہے، شرم کی چیز۔","e":"إِذَا دَخَلَ أَحَدُهُمْ الْخَلَاءَ جب ان میں سے کوئی بیت الخلاء میں داخل ہو، پہلا حصہ مبتداء وخبر جو ہے، یہ اس کی ظرف ہے، جو قید بن کر بیان ہوئی ہے۔ یعنی قضائے حاجت کے وقت جب آدمی ضروری ستر کھولے تو اس کے لیے بسم اللہ کہنا ضروری ہے، کیونکہ اللہ کا نام آدم کی اولاد کے لیے ایک مہر کی حیثیت رکھتا ہے، جسے شیطان توڑنے کی طاقت نہیں رکھتا۔ اس لیے اپنے تحفظ کے لیے اسے ضرور پڑھے۔ ۲۔ بہتر تو یہی ہے کہ بسم اللہ کے الفاظ پر اکتفا کیا جائے۔ (مرعاۃ: ۱/ ۴۲۸) ۳۔ اعتراض ہو سکتا ہے پہلے اس بیت الخلاء میں داخل ہونے والی دعاء کے ساتھ اعوذ باللہ آیا ہے، یہاں بسم اللہ ہے، کیا پڑھا جائے؟ اس کا حل یہ ہے کہ دونوں میں سے جو چاہے پڑھ لے جائز ہے، کیونکہ دونوں سنت سے ثابت ہیں۔ اور سب سے بہتر یہ ہے کہ بیت الخلاء میں جانے والی دعا یوں پڑھی جائے سب احادیث پر عمل ہو جاتا ہے۔ بِسْمِ اللهِ، اَعُوْذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ (فتح الباری، اسنادہ على شرط مسلم)"}],[484,"سیدنا سلمان فارسی رضی اللہ عنہ کو کہا گیا کہ تمہارے نبی صلی اللہ علیہ وسلم نے تمہیں ہر چیز کی تعلیم دیدی ہے یہاں تک کہ حاجت رفع کرنا بھی بتایا ہے۔ تو انہوں نے کہا ہاں بات اسی طرح ہے، آپ صلی اللہ علیہ وسلم نے ہمیں بول و براز کے وقت منہ قبلہ کی طرف کرنے سے بھی منع کیا ہے اور دائیں ہاتھ سے استنجا کرنے سے بھی منع کیا ہے، تین پتھروں سے کم استعمال کرنے کی ممانعت بھی کی ہے اور مینگنی اور ہڈی استعمال کرنے کی بھی ممانعت فرمائی ہے۔","",{"k":"مسلم (262)، کتاب الطهارة، ترمذی (16)، نسائی (41)، ابوداود (7)، ابن ماجہ (316)، احمد (23207)۔","m":"الْخِرَاءَةَ پاخانہ۔ أَجَلْ ہاں۔ أَنْ نَسْتَنْجِيَ استفعال سے جمع متکلم، مضارع معلوم۔ أَنْ نے نصب دیا ہے، ہم استنجاء کریں۔ بِرَجِيعٍ لید۔ بِعَظْمٍ ہڈی۔"}],[485,"ایک روایت میں ہے کہ یہ قائل مشرک تھا۔","",{"k":"مذکورہ بالا۔","m":"لَهُ سیدنا سلمان رضی اللہ عنہ سے کہنے والے۔","e":"۱۔ اس سے ثابت ہوا کہ مشرک نبی صلی اللہ علیہ وسلم پر طنز کا تیر برسا رہے تھے لیکن سیدنا سلمان رضی اللہ عنہ نے اسے سنجیدہ ماحول دے دیا کہ یہ مزاح کی بات نہیں بلکہ پیارے پیغمبر صلی اللہ علیہ وسلم نے حسن ادب سکھایا ہے، اس سے سیدنا سلمان رضی اللہ عنہ کی زیرکی اور دانائی کی جھلک نمایاں ہے۔ ۲۔ اس میں ایک ادب یہ بتایا گیا ہے کہ صحراء ہو یا عمارتیں ہوں پیشاب یا پاخانہ کے وقت نہ تو منہ قبلہ رخ کیا جائے اور نہ پیٹھ ہی کی جائے۔ ۳۔ دایاں ہاتھ اچھے کاموں کے استعمال کے لیے ہے، اس لیے اس کے ساتھ استنجاء نہ کیا جائے، چھوٹا استنجاء ہو یا بڑا ہو، استنجاء بائیں ہاتھ سے کیا جائے۔ ۴۔ اور نہ تین ڈھیلوں سے کم سے استنجاء کیا جائے۔ ایک حدیث میں آتا ہے کہ جو استنجاء کرے وہ وتر (طاق) کرے۔ اس کا مطلب یہ نہیں کہ ایک ڈھیلے سے بھی استنجاء ہوتا ہے، اس کا مطلب ہے کم از کم تین ہو اور اس سے زیادہ بھی استعمال کر سکتے ہیں مگر تعداد طاق رہے۔ ۵۔ لید، گوبر یا ہڈی سے بھی استنجاء کرنا منع ہے، ایک تو ان سے صحیح صفائی حاصل نہیں ہوتی اور پھر جو لید ہے اس سے جنوں کے جانوروں کا کھانا بنتا ہے اور ہڈی جنوں کی خوراک ہے۔ انہیں گندگی میں ملوث کرنا مناسب نہیں۔"}],[486,"سیدنا ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص پیشاب کرے تو ذکر کو دائیں ہاتھ سے نہ پکڑے اور نہ اس سے استنجا کرے اور برتن میں سانس بھی نہ لے۔‘‘ (بخاری)","",{"k":"بخاری (154)۔ مسلم (267)۔ ترمذی (15)۔ نسائی (47)۔ ابوداود (31)۔ ابن ماجہ (310)۔ احمد (22141)۔ دارمی (673)۔","m":"فَلَا يَأْخُذَنَّ، نَصَرَ سے مضارع معلوم، بانون تاکید ثقیلہ واحد مذکر غائب، ہرگز نہ پکڑے۔ وَلَا يَتَنَفَّسْ تفعّل سے نہی واحد مذکر غائب سانس نہ لے، ایک نسخہ میں مضارع منفی بھی ہے، اس صورت میں مستقل جملہ ہوگا۔ نہی ہو تو پہلے جملہ پر عطف ہے۔","e":"۱۔ پیشاب کی حالت میں دائیں ہاتھ کے ساتھ ذکر کو چھونے سے منع کر دیا گیا ہے۔ ابن حجر رحمہ اللہ فرماتے ہیں کہ ثابت ہوا پیشاب کی حالت میں دائیں ہاتھ سے ذکر کو چھونا منع ہے، اس کے علاوہ ضرورت کے وقت دایاں ہاتھ لگانا جائز ہے۔ (فتح الباری: ۱/۲۵۴) ۲۔ اس حدیث میں دائیں ہاتھ سے استنجاء کرنے پر بھی پابندی ہے، وجہ یہ ہے کہ دایاں ہاتھ کھانے کے لیے ہے اگر اس سے استنجاء کیا جائے تو پھر کھاتے وقت یاد آنے پر طبیعت مکدر ہو جاتی ہے۔ مسئلہ: اس سے یہ مسئلہ بھی استنباط ہوتا ہے کہ جس ہاتھ میں اللہ کے نام والی کندہ شدہ انگوٹھی ہے اس سے استنجا کرنا بالاولیٰ منع ہے، کیونکہ یہ دائیں ہاتھ سے زیادہ مقدس ہے اس کا حل یہ ہے کہ ہانگوٹھی اتار کر بیت الخلاء میں جایا جائے۔ ۳۔ برتن میں سانس لینے کی ممانعت اس لیے ہے کہ باقیماندہ کوئی اور بھی پی سکتا ہے اس طرح دوسرا بدمزہ ہوگا اور ویسے بھی پانی میں غلاظت گرنے کا اندیشہ ہوتا ہے۔"}],[487,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا دایاں ہاتھ طہارت اور کھانے پینے کے لیے مخصوص تھا اور بایاں ہاتھ بیت الخلاء اور ہر غیر طاہر چیز کے لیے۔ (ابوداؤد)","",{"k":"ابوداود (33)۔ احمد (24793)۔ صحیح البانی: 26۔","m":"لِخَلَائِهِ اصل میں قضائے حاجت کو کہتے ہیں، یہاں مراد استنجاء کرنا ہے، یعنی استنجاء کرنے کے لیے تھا۔ أَذًى نجاست وغیرہ کی صفائی کے لیے۔","e":"دائیں جانب اور دائیں ہاتھ کو یہ شرف حاصل ہے کہ لباس پہننے، موزے پہننے، مسجد میں داخل ہونے، مسواک کرنے، سرمہ ڈالنے، ناخن تراشنے، لہیں کاٹنے، بالوں میں کنگھی کرنے، زیر بغل بال اتارنے، سرمونڈنے، نماز سے سلام پھیرنے، طہارت کے اعضاء دھونے، بیت الخلاء سے نکلنے، کھانے، پینے، مصافحہ کرنے، حجر اسود کو چومنے وغیرہ ہر اچھے عمل میں دایاں ہاتھ یا جانب کو مقدم رکھا جائے۔ بیت الخلاء سے نکلنے، مسجد سے نکلنے، تھوک گرانے، لباس اتارنے، موزے وغیرہ اتارنے میں بایاں ہاتھ یا جانب استعمال کیے جائیں۔ (عون المعبود: ۱/۱۳)"}],[488,"سیدنا عثمان رضی اللہ عنہ نے کہا: جب سے میں نے دائیں ہاتھ سے رسول صلی اللہ علیہ وسلم کی بیعت کی ہے اس ہاتھ سے میں نے اپنے ذکر کو نہیں مس کیا اور پھر اس کی تفسیر کی کہ اپنے دائیں ہاتھ سے استنجا نہیں کیا (رزین)","",{"k":"رزین۔"}],[489,"ابو میمونہ سے مروی ہے اس نے کہا کہ میں نے انس بن مالک رضی اللہ عنہ سے سنا ہے کہ وہ کہتے جب رسول اللہ صلی اللہ علیہ وسلم حاجت رفع کرنے جاتے تو میں اور ہمارا ایک دوسرا لڑکا آپ صلی اللہ علیہ وسلم کے پیچھے پانی کا برتن لے کر جاتے۔","",{"k":"بخاری (151)۔ مسلم (271)۔ نسائی (45)۔ ابوداود (43)۔ احمد (13612)۔ دارمی (676)۔","m":"تَبِعْتُهُ، عَلِمَ سے ماضی واحد مذکر غائب، میں آپ صلی اللہ علیہ وسلم کے پیچھے جانا۔ وَغُلَامٌ چھوٹے بچے کو بھی کہتے ہیں اور بڑا ہوا سے بھی کہتے ہیں۔ إِدَاوَةٌ چمڑے کا لوٹا تھا۔"}],[490,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ جب نبی کریم صلی اللہ علیہ وسلم بیت الخلاء جاتے تو میں دو برتنوں میں پانی لاتا تو ایک سے آپ استنجا کرتے۔ وکیع کی حدیث میں ہے: پھر ہاتھ کو زمین پر رگڑتے تھے اور پھر میں دوسرے برتن میں پانی لاتا تو اس سے وضو کرتے۔","",{"k":"ابوداود (45)۔ دارمی (678)۔ حسن، البانی: 35۔","m":"تَوْرٌ پیتل یا پتھر کا برتن، تاء پر زبر ہے۔ رَكْوَةٌ چمڑے کا برتن۔","e":"۱۔ اس سے یہ ثابت ہوا کہ چھوٹے بچے سے خدمت لینا جائز ہے۔ ۲۔ اس سے ثابت ہوا کہ نبی صلی اللہ علیہ وسلم صرف پانی سے بھی استنجاء کیا کرتے تھے، دیگر روایات سے یہ ثابت ہوتا ہے کہ کبھی آپ فقط پتھر سے ہی استنجاء کیا کرتے۔ زیادہ تر آپ پہلے پتھر اور بعد میں پانی استعمال کرتے تھے۔ (مرعاۃ: ۱/۴۱۷) ۳۔ اس سے یہ بھی ثابت ہوا کہ پیتل کے برتن میں سے وضو کرنا جائز ہے۔ ۴۔ صحابی رضی اللہ عنہ جو کہتے ہیں کہ میں آپ کے لیے اور برتن لایا تو آپ نے اس سے وضو کیا۔ اس سے شبہ ہوسکتا ہے کہ استنجاء سے باقی بچا ہوا پانی جو ہے اس سے وضو جائز نہیں یا جس برتن سے استنجاء کیا ہے اس میں سے وضو کرنا جائز نہیں۔ یہ مفہوم اخذ کرنا درست نہیں۔ استنجاء سے باقیماندہ پانی سے وضو بھی جائز ہے اس برتن سے وضو بھی جائز ہے، صحابی رضی اللہ عنہ یہ دوسرا برتن اس لیے لائے تھے کہ اتفاق ایسا ہوا کہ اس میں پانی نہیں رہا تھا یا پانی کم پڑ گیا تھا، اس لیے وہ پانی اور لائے تھے۔ (عون المعبود: ۱/۱۶)"}],[491,"سیدنا ابوہریرہ رضی اللہ عنہ مرفوع بیان کرتے ہیں: جبرئیل علیہ السلام آئے اور فرمایا: یا محمد (صلی اللہ علیہ وسلم)! جب تو وضو کرے تو پانی چھڑک دیا کر۔ (ترمذی)","",{"k":"ترمذی (50)۔ ابن ماجہ (464)۔ ضعیف، البانی: 6۔"}],[492,"سفیان بن حکم رضی اللہ عنہ یا حکم بن سفیان نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم جب پیشاب کرتے اور وضو کرتے تو پانی چھڑکتے تھے۔ (ابوداؤد)","",{"k":"ابوداود (166)۔ ابن ماجہ (463)۔ صحیح، البانی: 152۔","m":"يَنْتَضِحُ افتعال سے مضارع معلوم واحد مذکر غائب، پانی چھڑکتے۔"}],[493,"حکم اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب وضو کرتے تو آپ میں پانی لے کر اس طرح کرتے۔ شعبہ نے اس کی تفسیر کی کہ اپنے مخفی مقام پر چھڑک دیتے تھے۔","",{"k":"نسائی (134)۔ ابوداود (168)۔ ابن ماجہ (461)۔ احمد (22959)۔","m":"حَفْنَةً چلو۔"}],[494,"عبد الرحمن بن عبد اللہ سے روایت ہے کہ اس نے عمر رضی اللہ عنہ سے سنا جب وضو کرتے تو ازار کے نیچے پانی ڈالتے۔","",{"k":"موطا (37)۔ صحیح۔","m":"يَتَوَضَّأُ تفعّل سے مضارع معلوم واحد مذکر غائب، وضو کرتے، یہاں مراد استنجا ہے۔ إِزَارِهِ اپنے تہبند، استنجاء کی جگہ مراد ہے۔","e":"۱۔ سیدنا عمر رضی اللہ عنہ والی بات سے ان لوگوں کی تردید ہوتی ہے جو پانی سے استنجاء کرنا ناپسند تصور کرتے ہیں۔ اس سے ثابت ہوتا ہے کہ پانی سے استنجاء کرنا افضل ہے۔ (زرقانی: ۱/۴۸) ۲۔ اور تمام احادیث کا خلاصہ یہی ہے کہ وضو سے فراغت کے بعد معمولی سا پانی لے کر شرمگاہ پر چھینٹے مارے جائیں تا کہ وسوسہ وغیرہ ختم ہو جائے۔ علامہ عبید اللہ رحمہ اللہ فرماتے ہیں: ٹھنڈے پانی سے چھینٹے مارنے کی وجہ سے پیشاب اترنا رک جاتا ہے، اس لیے بھی وضو کے بعد آپ نے ایسا کرنے کی امت کو تعلیم دی ہے۔ (مرعاۃ: ۱/۴۳۳)"}],[495,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے: رسول اللہ صلی اللہ علیہ وسلم نے پیشاب کیا تو عمر رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے پیچھے کوزے میں پانی لے کر کھڑے ہوئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے عمر! یہ کیا ہے؟‘‘ انہوں نے عرض کی: پانی ہے آپ صلی اللہ علیہ وسلم کے وضو کرنے کے لیے۔ فرمایا: مجھے تو یہ حکم نہیں دیا گیا کہ جب میں پیشاب کروں تو وضو کیا کروں اور اگر میں ایسا کروں تو یہ سنت بن جائے گا۔‘‘ (ابوداؤد)","",{"k":"ابوداود (42)۔ احمد (24122)۔ ضعیف، البانی: 10۔"}]])